{
  "name": "LinguaTale - AI Language Story Generator",
  "description": "Generate CEFR-level appropriate stories for language learners in 24 EU languages with strict linguistic constraints."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Language = 
  | "Bulgarian" | "Croatian" | "Czech" | "Danish" | "Dutch" | "English" 
  | "Estonian" | "Finnish" | "French" | "German" | "Greek" | "Hungarian" 
  | "Irish" | "Italian" | "Latvian" | "Lithuanian" | "Maltese" | "Polish" 
  | "Portuguese" | "Romanian" | "Slovak" | "Slovenian" | "Spanish" | "Swedish";

export type CEFRLevel = 
  | "A1.1" | "A1.2" | "A1.3" 
  | "A2.1" | "A2.2" 
  | "B1.1" | "B1.2" 
  | "B2.1" | "B2.2" 
  | "C1-C2";

export type TopicOption = 
  | "Grocery Shopping" 
  | "At the Doctor" 
  | "Asking for Directions" 
  | "Ordering Coffee" 
  | "Job Interview" 
  | "Family Gathering"
  | "Public Transport"
  | "Weather Talk"
  | "Custom Topic";

export interface StoryResponse {
  title: string;
  content: string;
  englishTranslation: string;
  vocabulary: Array<{ term: string; definition: string }>;
}

export interface GenerationState {
  isLoading: boolean;
  error: string | null;
  data: StoryResponse | null;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CEFRLevel, Language, StoryResponse } from "../types";

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    title: {
      type: Type.STRING,
      description: "The title of the story in the target language."
    },
    content: {
      type: Type.STRING,
      description: "The main body of the story in the target language."
    },
    englishTranslation: {
      type: Type.STRING,
      description: "A full English translation of the story."
    },
    vocabulary: {
      type: Type.ARRAY,
      description: "A list of 5-10 key vocabulary words used in the story.",
      items: {
        type: Type.OBJECT,
        properties: {
          term: { type: Type.STRING, description: "The word in the target language" },
          definition: { type: Type.STRING, description: "The English definition" }
        }
      }
    }
  },
  required: ["title", "content", "englishTranslation", "vocabulary"]
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string
): Promise<StoryResponse> => {

  // Construct linguistic constraints based on level
  let linguisticConstraints = "";

  if (level.startsWith("A1") || level.startsWith("A2")) {
    linguisticConstraints += "Vocabulary must be strictly high-frequency. Sentences must be simple and short. Avoid idioms.";
  } else if (level.startsWith("B1") || level.startsWith("B2")) {
    linguisticConstraints += "Vocabulary can include common daily topics. Sentences can use compound structures (and, but, because).";
  } else {
    linguisticConstraints += "Natural, native-like complexity allowed. Advanced vocabulary and nuanced grammar.";
  }

  // Language specific constraints
  if (language === "Finnish") {
    if (level === "A1.1" || level === "A1.2" || level === "A1.3") {
      linguisticConstraints += " CRITICAL FINNISH RULE: Use mostly Nominative, Genitive, and Partitive cases. strictly AVOID complex cases like Translative or Essive. Use simple Present tense.";
    } else if (level.startsWith("A2")) {
      linguisticConstraints += " CRITICAL FINNISH RULE: Introduce local cases (Inessive, Elative, Illative, Adessive, Ablative, Allative) sparingly. Keep sentence structure SVO where possible.";
    }
  }

  const prompt = `
    Task: Write a short story for a language learner.
    Target Language: ${language}
    CEFR Level: ${level}
    Topic: ${topic}

    Linguistic Constraints:
    ${linguisticConstraints}

    The story should be engaging but strictly adhere to the requested proficiency level.
    Provide the output in JSON format containing the Title, Story Content, English Translation, and a Vocabulary list.
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", // Efficient for text generation tasks
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7, // Slightly creative but grounded
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate story. Please verify your API key and try again.");
  }
};

import React from 'react';
import { ChevronDown } from 'lucide-react';

interface SelectorProps<T extends string> {
  label: string;
  value: T;
  options: T[];
  onChange: (value: T) => void;
  disabled?: boolean;
}

export const Selector = <T extends string>({ 
  label, 
  value, 
  options, 
  onChange, 
  disabled 
}: SelectorProps<T>) => {
  return (
    <div className="flex flex-col space-y-2">
      <label className="text-sm font-semibold text-gray-700">
        {label}
      </label>
      <div className="relative">
        <select
          value={value}
          onChange={(e) => onChange(e.target.value as T)}
          disabled={disabled}
          className="w-full appearance-none rounded-lg border border-gray-300 bg-white px-4 py-3 pr-10 text-gray-700 shadow-sm focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 disabled:bg-gray-100 disabled:text-gray-400"
        >
          {options.map((opt) => (
            <option key={opt} value={opt}>
              {opt}
            </option>
          ))}
        </select>
        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-3 text-gray-500">
          <ChevronDown className="h-4 w-4" />
        </div>
      </div>
    </div>
  );
};

