                <Selector 
                  label="Target Language" 
                  value={language} 
                  options={LANGUAGES} 
                  onChange={setLanguage}
                  disabled={generation.isLoading}
                />

                <Selector 
                  label="CEFR Level" 
                  value={level} 
                  options={LEVELS} 
                  onChange={setLevel}
                  disabled={generation.isLoading}
                />

                <div className="space-y-4">
                  <Selector 
                    label="Topic" 
                    value={topicType} 
                    options={TOPICS} 
                    onChange={setTopicType}
                    disabled={generation.isLoading}
                  />

                  {topicType === "Custom Topic" && (
                    <div className="animate-fade-in">
                      <label className="mb-2 block text-sm font-semibold text-gray-700">
                        Describe your topic
                      </label>
                      <input
                        type="text"
                        value={customTopic}
                        onChange={(e) => setCustomTopic(e.target.value)}
                        placeholder="e.g., A lost cat in space..."
                        className="w-full rounded-lg border border-gray-300 px-4 py-3 shadow-sm focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 disabled:bg-gray-100"
                        disabled={generation.isLoading}
                        autoFocus
                      />
                    </div>
                  )}
                </div>

                <div className="pt-2">
                  <button
                    onClick={handleGenerate}
                    disabled={generation.isLoading || (topicType === "Custom Topic" && !customTopic.trim())}
                    className="flex w-full items-center justify-center rounded-xl bg-indigo-600 px-4 py-4 font-bold text-white shadow-md transition-all hover:bg-indigo-700 hover:shadow-lg hover:shadow-indigo-500/20 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:bg-gray-300 disabled:shadow-none"
