                </div>
                <h3 className="text-xl font-medium text-gray-500">Ready to read?</h3>
                <p className="mt-1 text-gray-400">Select your settings and click generate.</p>
              </div>
            )}

            {generation.data && (
              <StoryDisplay 
                story={generation.data} 
                language={language}
                level={level}
              />
            )}
          </div>

        </div>
      </main>
    </div>
  );
};

export default App;

