    1. Title
    2. Content (Story text with embedded {word|translation} markup)
    3. EnglishTranslation (Full text translation)
    4. Vocabulary (List of words for the summary section)
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", // Efficient for text generation tasks
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7, // Slightly creative but grounded
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate story. Please verify your API key and try again.");
  }
};

import React, { useState, useMemo } from 'react';
import { BookOpen, Languages, Sparkles } from 'lucide-react';
import { StoryResponse } from '../types';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  level: string;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
  id?: number;
}

const parseStoryContent = (text: string): TextSegment[] => {
  // Regex to match {word|translation} pattern
  // [^|]+ matches one or more characters that are not a pipe
  // [^}]+ matches one or more characters that are not a closing brace
  const regex = /\{([^|]+)\|([^}]+)\}/g;
  const segments: TextSegment[] = [];
  let lastIndex = 0;
  let match;
  let idCounter = 0;

  while ((match = regex.exec(text)) !== null) {
    // Push preceding text if it exists
    if (match.index > lastIndex) {
      segments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    // Push the vocabulary item
    segments.push({
      type: 'vocab',
      content: match[1].trim(),
      translation: match[2].trim(),
      id: idCounter++
    });

    lastIndex = regex.lastIndex;
  }

  // Push remaining text
  if (lastIndex < text.length) {
    segments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  return segments;
};

