import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CEFRLevel, Language, StoryResponse, StoryStyle } from "../types";

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    title: {
      type: Type.STRING,
      description: "The title of the story in the target language."
    },
    content: {
      type: Type.STRING,
      description: "The main body of the story in the target language. Use \\n\\n to separate paragraphs."
    },
    englishTranslation: {
      type: Type.STRING,
      description: "A full English translation of the story."
    },
    quiz: {
      type: Type.ARRAY,
      description: "A reading comprehension quiz with 3 questions.",
      items: {
        type: Type.OBJECT,
        properties: {
          question: { type: Type.STRING, description: "The question in English." },
          options: { 
            type: Type.ARRAY, 
            description: "3 possible answers.",
            items: { type: Type.STRING } 
          },
          correctAnswer: { type: Type.STRING, description: "The correct answer string, which must match one of the options." }
        },
        required: ["question", "options", "correctAnswer"]
      }
    }
  },
  required: ["title", "content", "englishTranslation", "quiz"]
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string,
  style: StoryStyle
): Promise<StoryResponse> => {

  // Construct linguistic constraints based on level
  let linguisticConstraints = "";

  if (level.startsWith("A1") || level.startsWith("A2")) {
    linguisticConstraints += "Vocabulary must be strictly high-frequency. Sentences must be simple and short. Avoid idioms.";
  } else if (level.startsWith("B1") || level.startsWith("B2")) {
    linguisticConstraints += "Vocabulary can include common daily topics. Sentences can use compound structures (and, but, because).";
  } else {
    linguisticConstraints += "Natural, native-like complexity allowed. Advanced vocabulary and nuanced grammar.";
  }

  // Language specific constraints
  if (language === "Finnish") {
    if (level === "A1.1" || level === "A1.2" || level === "A1.3") {
      linguisticConstraints += " CRITICAL FINNISH RULE: Use mostly Nominative, Genitive, and Partitive cases. strictly AVOID complex cases like Translative or Essive. Use simple Present tense.";
    } else if (level.startsWith("A2")) {
      linguisticConstraints += " CRITICAL FINNISH RULE: Introduce local cases (Inessive, Elative, Illative, Adessive, Ablative, Allative) sparingly. Keep sentence structure SVO where possible.";
    }
  }

  const prompt = `
    Task: Write a COMPREHENSIVE story for a language learner.
    Target Language: ${language}
    CEFR Level: ${level}
    Topic: ${topic}
    Style/Tone: ${style}

    Structure & Length:
    - The story MUST be substantial in length (approx 400-600 words).
    - Break the story into 3-5 clear paragraphs. Use double newlines (\\n\\n) to separate them.
    - Avoid "walls of text".

    Linguistic Constraints:
    ${linguisticConstraints}

    Interactive Vocabulary Requirement:
    Identify 15-20 key vocabulary words or phrases appropriate for the level within the story.
    You MUST embed these English translations directly into the story text using the format: {target_word|english_translation}.
    Example: "The {kissa|cat} sat on the {matto|mat}."

    Quiz Requirement:
    Create a reading comprehension quiz with 3 questions in English to test understanding of the story.

    Output Format:
    Provide the output in JSON format matching the schema containing:
    1. Title
    2. Content (Story text with paragraphs and embedded {word|translation} markup)
    3. EnglishTranslation (Full text translation)
    4. Quiz (Array of 3 questions)
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate story. Please verify your API key and try again.");
  }
};

