    Quiz Requirement:
    - Create 3 reading comprehension questions based ONLY on this new part of the story.
    - CRITICAL: The questions and the answer options MUST BE IN ${language.toUpperCase()} (The Target Language).
    - Do NOT write the quiz in English.

    Output Format:
    Return valid JSON matching the schema:
    {
      "title": "Title (or Chapter Name) in ${language}",
      "content": "Story text...",
      "englishTranslation": "Full English translation...",
      "quiz": [
        { "question": "Question in ${language}?", "options": ["Option A", "Option B", "Option C"], "correctAnswer": "Option A" }
      ]
    }
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.6, 
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
