import React, { useState, useEffect } from 'react';
import { BookMarked, Sparkles, Send, Tag } from 'lucide-react';
import { LANGUAGES, LEVELS, SUGGESTED_TOPICS, STORY_STYLES, LEVEL_DESCRIPTIONS } from './constants';
import { Language, CEFRLevel, GenerationState, StoryStyle, StoryResponse } from './types';
import { Selector } from './components/Selector';
import { StoryDisplay } from './components/StoryDisplay';
import { LoadingState } from './components/LoadingState';
import { generateStory } from './services/geminiService';

const STORAGE_KEYS = {
  LANGUAGE: 'linguatale_pref_language',
  LEVEL: 'linguatale_pref_level',
  STYLE: 'linguatale_pref_style'
};

const App: React.FC = () => {
  // Form State - Initialize from LocalStorage or default
  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LANGUAGE);
    return (saved && LANGUAGES.includes(saved as Language)) ? (saved as Language) : "English";
  });

  const [level, setLevel] = useState<CEFRLevel>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LEVEL);
    return (saved && LEVELS.includes(saved as CEFRLevel)) ? (saved as CEFRLevel) : "A1.1";
  });

  const [storyStyle, setStoryStyle] = useState<StoryStyle>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.STYLE);
    return (saved && STORY_STYLES.includes(saved as StoryStyle)) ? (saved as StoryStyle) : "Standard";
  });

  const [storyDescription, setStoryDescription] = useState<string>("");

  // Save preferences whenever they change
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.LANGUAGE, language);
  }, [language]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.LEVEL, level);
  }, [level]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.STYLE, storyStyle);
  }, [storyStyle]);

  // Story Pagination State
  const [storyPages, setStoryPages] = useState<StoryResponse[]>([]);
  const [pageIndex, setPageIndex] = useState<number>(-1);
  const [isGeneratingNext, setIsGeneratingNext] = useState(false);

  // API State (for initial generation or general errors)
  const [generation, setGeneration] = useState<GenerationState>({
    isLoading: false,
    error: null,
    data: null
  });

  const handleTagClick = (tag: string) => {
    setStoryDescription((prev) => {
      const trimmed = prev.trim();
      if (!trimmed) return tag;
      return `${trimmed}, ${tag}`;
    });
  };

  // Generate the FIRST page of a new story
  const handleGenerate = async () => {
    if (!storyDescription.trim()) {
      alert("Please describe the story or select a topic.");
      return;
    }

    setGeneration({ isLoading: true, error: null, data: null });
    setStoryPages([]);
    setPageIndex(-1);

    try {
      const data = await generateStory(language, level, storyDescription, storyStyle);
      setStoryPages([data]);
      setPageIndex(0);
      setGeneration({
        isLoading: false,
        error: null,
        data: null // We use storyPages now
      });
    } catch (err: any) {
      setGeneration({
        isLoading: false,
        error: err.message || "An unexpected error occurred.",
        data: null
      });
    }
  };

  // Navigate to previous page
  const handlePrevPage = () => {
    if (pageIndex > 0) {
      setPageIndex(pageIndex - 1);
    }
  };

  // Navigate to next page OR generate it
  const handleNextPage = async () => {
    // If we already have the next page in history, just go there
    if (pageIndex < storyPages.length - 1) {
      setPageIndex(pageIndex + 1);
      return;
    }

    // Otherwise, generate the next chapter
    setIsGeneratingNext(true);
    try {
      // Get content of the current page to use as context
      const currentContent = storyPages[pageIndex].content;

      const newPage = await generateStory(
        language, 
        level, 
        storyDescription, 
        storyStyle,
        currentContent // Pass previous context
      );

      setStoryPages(prev => [...prev, newPage]);
      setPageIndex(prev => prev + 1);
    } catch (err: any) {
      console.error("Failed to generate next page", err);
      // Optional: Show a toast or alert, but we'll keep the current page visible
      alert("Failed to generate the next chapter. Please try again.");
    } finally {
      setIsGeneratingNext(false);
    }
  };

  // Helper to determine what to display
  const currentStory = pageIndex >= 0 && storyPages.length > pageIndex ? storyPages[pageIndex] : null;

  return (
    <div className="min-h-screen bg-gray-50 px-4 py-8 sm:px-6 lg:px-8">
      {/* Navbar / Header */}
      <header className="mx-auto max-w-7xl mb-10 text-center">
        <div className="flex items-center justify-center space-x-3 mb-2">
            <div className="p-2 bg-indigo-600 rounded-lg text-white">
                <BookMarked className="w-8 h-8" />
            </div>
            <h1 className="text-3xl font-bold tracking-tight text-gray-900 sm:text-4xl">
            LinguaTale
            </h1>
        </div>
        <p className="text-lg text-gray-600 max-w-2xl mx-auto">
          AI-powered stories tailored to your exact language proficiency level.
        </p>
      </header>

      <main className="mx-auto max-w-7xl">
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12">

          {/* Left Column: Controls */}
          <div className="lg:col-span-4">
            <div className="sticky top-8 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-gray-900/5">
              <div className="bg-gradient-to-r from-indigo-500 to-purple-600 px-6 py-4">
                <h2 className="flex items-center text-lg font-semibold text-white">
                  <Sparkles className="mr-2 h-5 w-5" />
                  Story Settings
                </h2>
              </div>

              <div className="space-y-6 p-6">
                <Selector<Language> 
                  label="Target Language" 
                  value={language} 
                  options={LANGUAGES} 
                  onChange={setLanguage}
                  disabled={generation.isLoading || isGeneratingNext}
                />

                <Selector<CEFRLevel> 
                  label="Language Level" 
                  value={level} 
                  options={LEVELS} 
                  onChange={setLevel}
                  disabled={generation.isLoading || isGeneratingNext}
                  getLabel={(opt) => LEVEL_DESCRIPTIONS[opt]}
                />

                <Selector<StoryStyle> 
                  label="Story Style" 
                  value={storyStyle} 
                  options={STORY_STYLES} 
                  onChange={setStoryStyle}
                  disabled={generation.isLoading || isGeneratingNext}
                />

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-gray-700">
                    Story Description
                  </label>
                  <textarea
                    value={storyDescription}
                    onChange={(e) => setStoryDescription(e.target.value)}
                    placeholder="Describe your story topics (e.g., shopping, lost wallet, police station)..."
                    className="w-full h-32 resize-none rounded-lg border border-gray-300 bg-white text-gray-900 px-4 py-3 shadow-sm focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 disabled:bg-gray-100 placeholder:text-gray-400"
                    disabled={generation.isLoading || isGeneratingNext}
                  />

                  {/* Tag Cloud */}
                  <div className="pt-2">
                    <div className="flex items-center gap-1 mb-2 text-xs font-medium text-gray-500 uppercase tracking-wide">
                        <Tag className="w-3 h-3" />
                        <span>Suggested Topics</span>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {SUGGESTED_TOPICS.map((tag) => (
                        <button
                          key={tag}
                          onClick={() => handleTagClick(tag)}
                          disabled={generation.isLoading || isGeneratingNext}
                          className="px-3 py-1 text-xs font-medium text-indigo-700 bg-indigo-50 rounded-full border border-indigo-100 hover:bg-indigo-100 hover:border-indigo-200 transition-colors active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                          + {tag}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="pt-2">
                  <button
                    onClick={handleGenerate}
                    disabled={generation.isLoading || isGeneratingNext || !storyDescription.trim()}
                    className="flex w-full items-center justify-center rounded-xl bg-indigo-600 px-4 py-4 font-bold text-white shadow-md transition-all hover:bg-indigo-700 hover:shadow-lg hover:shadow-indigo-500/20 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:bg-gray-300 disabled:shadow-none"
                  >
                    {generation.isLoading ? "Starting Story..." : (
                        <>
                            New Story <Send className="ml-2 h-4 w-4" />
                        </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Right Column: Display */}
          <div className="flex flex-col items-center lg:col-span-8">
            {generation.isLoading && <LoadingState message="Creating your first chapter..." />}

            {generation.error && (
              <div className="w-full rounded-xl border border-red-200 bg-red-50 p-4 text-center text-red-700">
                <p className="font-medium">Error generating story</p>
                <p className="text-sm">{generation.error}</p>
              </div>
            )}

            {!generation.isLoading && !generation.error && !currentStory && (
              <div className="flex h-96 w-full flex-col items-center justify-center rounded-3xl border-2 border-dashed border-gray-200 bg-white/50 text-center">
                <div className="mb-4 rounded-full bg-indigo-50 p-4">
                  <BookMarked className="h-10 w-10 text-indigo-200" />
                </div>
                <h3 className="text-xl font-medium text-gray-500">Ready to read?</h3>
                <p className="mt-1 text-gray-400">Describe your story topics and click New Story.</p>
              </div>
            )}

            {currentStory && (
              <StoryDisplay 
                story={currentStory} 
                language={language}
                level={level}
                onNextPage={handleNextPage}
                onPrevPage={handlePrevPage}
                canGoNext={true} // Always allow trying for next page
                canGoPrev={pageIndex > 0}
                isGeneratingNext={isGeneratingNext}
                currentPage={pageIndex + 1}
              />
            )}
          </div>

        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { BookOpen, Languages, HelpCircle, CheckCircle2, XCircle, ArrowLeft, ArrowRight, Loader2 } from 'lucide-react';
import { StoryResponse } from '../types';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  level: string;
  onNextPage: () => void;
  onPrevPage: () => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  isGeneratingNext: boolean;
  currentPage: number;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
}

// Parses a single string (paragraph) into segments of text and interactive vocab words
const parseParagraph = (text: string): TextSegment[] => {
  const regex = /\{([^|]+)\|([^}]+)\}/g;
  const segments: TextSegment[] = [];
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      segments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    segments.push({
      type: 'vocab',
      content: match[1].trim(),
      translation: match[2].trim()
    });

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    segments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  return segments;
};

export const StoryDisplay: React.FC<StoryDisplayProps> = ({ 
  story, 
  language, 
  level,
  onNextPage,
  onPrevPage,
  canGoPrev,
  canGoNext,
  isGeneratingNext,
  currentPage
}) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, string>>({});

  // Reset local state when story changes (pagination)
  useEffect(() => {
    setShowTranslation(false);
    setActiveTooltipId(null);
    setQuizAnswers({});
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [story]);

  // Split story content into paragraphs
  const paragraphs = useMemo(() => {
    if (!story.content) return [];

    // Handle edge case where model produces literal "\n" string characters instead of control characters
    const normalizedContent = story.content.replace(/\\n/g, '\n');

    // Split by one or more newline characters to ensure distinct paragraphs are created
    return normalizedContent.split(/\n+/).filter(p => p.trim().length > 0);
  }, [story.content]);

  const handleBackgroundClick = () => {
    setActiveTooltipId(null);
  };

  const handleQuizOptionClick = (questionIndex: number, option: string) => {
    setQuizAnswers(prev => ({
      ...prev,
      [questionIndex]: option
    }));
  };

  return (
    <div className="animate-fade-in-up w-full max-w-3xl overflow-hidden rounded-2xl bg-white shadow-xl ring-1 ring-gray-900/5">
      {/* Header */}
      <div className="border-b border-gray-100 bg-indigo-600 px-6 py-4 text-white">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <BookOpen className="h-5 w-5" />
            <span className="font-medium opacity-90">{language} Story</span>
          </div>
          <div className="flex items-center gap-3">
             <span className="opacity-75 text-xs font-medium uppercase tracking-wider">Page {currentPage}</span>
             <span className="rounded-full bg-white/20 px-3 py-1 text-xs font-bold text-white">
                Level {level}
            </span>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="space-y-8 px-6 py-8 sm:px-8">

        {/* Story Section */}
        <section onClick={handleBackgroundClick}>
          <h2 className="mb-6 text-2xl font-bold text-gray-900 sm:text-3xl text-center">
            {story.title}
          </h2>

          <div className="prose prose-lg max-w-none text-gray-700">
            {paragraphs.map((paragraph, pIndex) => {
              const segments = parseParagraph(paragraph);

              return (
                <p key={pIndex} className="mb-6 leading-relaxed last:mb-0">
                  {segments.map((segment, sIndex) => {
                    if (segment.type === 'text') {
                      return <span key={sIndex}>{segment.content}</span>;
                    }

                    // Create a unique ID for this segment based on paragraph and segment index
                    const uniqueId = `${pIndex}-${sIndex}`;
                    const isOpen = activeTooltipId === uniqueId;

                    return (
                      <span key={sIndex} className="relative inline-block mx-0.5 align-baseline">
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveTooltipId(isOpen ? null : uniqueId);
                          }}
                          className={`
                            cursor-pointer rounded-sm border-b-2 font-semibold transition-colors outline-none
                            ${isOpen 
                              ? 'border-indigo-600 bg-indigo-50 text-indigo-900' 
                              : 'border-indigo-300 text-indigo-800 hover:bg-indigo-50'
                            }
                          `}
                        >
                          {segment.content}
                        </button>

                        {isOpen && (
                          <div className="absolute bottom-full left-1/2 mb-2 z-50 -translate-x-1/2">
                            <div className="animate-fade-in relative rounded-lg bg-gray-900 px-3 py-2 text-sm font-medium text-white shadow-xl">
                              <span className="whitespace-nowrap">{segment.translation}</span>
                              <div className="absolute top-full left-1/2 -ml-1.5 -mt-1 h-3 w-3 -translate-x-1/2 rotate-45 bg-gray-900"></div>
                            </div>
                          </div>
                        )}
                      </span>
                    );
                  })}
                </p>
              );
            })}
          </div>
        </section>

        {/* Translation Toggle */}
        <div className="flex justify-center border-t border-gray-100 pt-6">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-medium text-indigo-600 hover:text-indigo-800 focus:outline-none transition-colors"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? "Hide Full Translation" : "Show Full Translation"}</span>
            </button>
        </div>

        {/* Translation Section */}
        {showTranslation && (
            <div className="animate-fade-in rounded-xl bg-gray-50 p-6 text-gray-600 ring-1 ring-gray-900/5">
                <h3 className="mb-3 text-xs font-bold uppercase tracking-wider text-gray-400">English Translation</h3>
                <p className="whitespace-pre-line leading-relaxed">{story.englishTranslation}</p>
            </div>
        )}

        {/* Quiz Section */}
        <div className="mt-8 border-t border-gray-100 pt-8">
            <div className="flex items-center space-x-2 mb-6">
                <HelpCircle className="h-5 w-5 text-indigo-600" />
                <h3 className="text-xl font-bold text-gray-900">Comprehension Quiz</h3>
            </div>

            <div className="space-y-6">
              {story.quiz.map((item, index) => {
                const selectedAnswer = quizAnswers[index];
                const isCorrect = selectedAnswer === item.correctAnswer;
                const hasAnswered = selectedAnswer != null;

                return (
                  <div key={index} className="rounded-xl border border-gray-200 bg-gray-50/50 p-5 transition-all hover:bg-white hover:shadow-sm">
                    <p className="mb-4 font-medium text-gray-900">
                      <span className="mr-2 text-indigo-600">{index + 1}.</span>
                      {item.question}
                    </p>

                    <div className="space-y-2">
                      {item.options.map((option) => {
                        let buttonStyle = "border-gray-200 bg-white text-gray-700 hover:border-indigo-300 hover:bg-indigo-50";
                        let icon = null;

                        if (hasAnswered) {
                           if (option === item.correctAnswer) {
                             buttonStyle = "border-green-500 bg-green-50 text-green-700 ring-1 ring-green-500";
                             icon = <CheckCircle2 className="h-4 w-4 text-green-600" />;
                           } else if (option === selectedAnswer) {
                             buttonStyle = "border-red-300 bg-red-50 text-red-700";
                             icon = <XCircle className="h-4 w-4 text-red-500" />;
                           } else {
                             buttonStyle = "border-gray-200 bg-gray-50 text-gray-400 opacity-60";
                           }
                        }

                        return (
                          <button
                            key={option}
                            onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                            disabled={hasAnswered}
                            className={`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left text-sm font-medium transition-all ${buttonStyle} ${!hasAnswered ? 'active:scale-[0.99]' : ''}`}
                          >
                            <span>{option}</span>
                            {icon}
                          </button>
                        );
                      })}
                    </div>

                    {hasAnswered && isCorrect && (
                      <p className="mt-2 text-xs font-bold text-green-600 animate-fade-in">Correct!</p>
                    )}
                    {hasAnswered && !isCorrect && (
                      <p className="mt-2 text-xs font-bold text-red-500 animate-fade-in">Incorrect, the answer was {item.correctAnswer}</p>
                    )}
                  </div>
                );
              })}
            </div>
        </div>
      </div>

      {/* Pagination Footer */}
      <div className="border-t border-gray-100 bg-gray-50 px-6 py-4">
        <div className="flex items-center justify-between">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg px-4 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-200 hover:text-gray-900 disabled:opacity-30 disabled:hover:bg-transparent"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>Previous Page</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg bg-indigo-600 px-5 py-2 text-sm font-medium text-white shadow-sm transition-all hover:bg-indigo-700 hover:shadow disabled:opacity-70 disabled:shadow-none"
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>Creating Next Page...</span>
                     </>
                ) : (
                    <>
                        <span>Next Page</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>
      </div>

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { BookMarked, Sparkles, Send, Tag } from 'lucide-react';
import { LANGUAGES, LEVELS, SUGGESTED_TOPICS, STORY_STYLES, LEVEL_DESCRIPTIONS } from './constants';
import { Language, CEFRLevel, GenerationState, StoryStyle, StoryResponse } from './types';
import { Selector } from './components/Selector';
import { StoryDisplay } from './components/StoryDisplay';
import { LoadingState } from './components/LoadingState';
import { generateStory } from './services/geminiService';

const STORAGE_KEYS = {
  LANGUAGE: 'linguatale_pref_language',
  LEVEL: 'linguatale_pref_level',
  STYLE: 'linguatale_pref_style'
};

const App: React.FC = () => {
  // Form State - Initialize from LocalStorage or default
  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LANGUAGE);
    return (saved && LANGUAGES.includes(saved as Language)) ? (saved as Language) : "English";
  });

  const [level, setLevel] = useState<CEFRLevel>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LEVEL);
    return (saved && LEVELS.includes(saved as CEFRLevel)) ? (saved as CEFRLevel) : "A1.1";
  });

  const [storyStyle, setStoryStyle] = useState<StoryStyle>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.STYLE);
    return (saved && STORY_STYLES.includes(saved as StoryStyle)) ? (saved as StoryStyle) : "Standard";
  });

  const [storyDescription, setStoryDescription] = useState<string>("");

  // Save preferences whenever they change
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.LANGUAGE, language);
  }, [language]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.LEVEL, level);
  }, [level]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.STYLE, storyStyle);
  }, [storyStyle]);

  // Story Pagination State
  const [storyPages, setStoryPages] = useState<StoryResponse[]>([]);
  const [pageIndex, setPageIndex] = useState<number>(-1);
  const [isGeneratingNext, setIsGeneratingNext] = useState(false);

  // API State (for initial generation or general errors)
  const [generation, setGeneration] = useState<GenerationState>({
    isLoading: false,
    error: null,
    data: null
  });

  const handleTagClick = (tag: string) => {
    setStoryDescription((prev) => {
      const trimmed = prev.trim();
      if (!trimmed) return tag;
      return `${trimmed}, ${tag}`;
    });
  };

  // Generate the FIRST page of a new story
  const handleGenerate = async () => {
    if (!storyDescription.trim()) {
      alert("Please describe the story or select a topic.");
      return;
    }

    setGeneration({ isLoading: true, error: null, data: null });
    setStoryPages([]);
    setPageIndex(-1);

    try {
      const data = await generateStory(language, level, storyDescription, storyStyle);
      setStoryPages([data]);
      setPageIndex(0);
      setGeneration({
        isLoading: false,
        error: null,
        data: null // We use storyPages now
      });
    } catch (err: any) {
      setGeneration({
        isLoading: false,
        error: err.message || "An unexpected error occurred.",
        data: null
      });
    }
  };

  // Navigate to previous page
  const handlePrevPage = () => {
    if (pageIndex > 0) {
      setPageIndex(pageIndex - 1);
    }
  };

  // Navigate to next page OR generate it
  const handleNextPage = async () => {
    // If we already have the next page in history, just go there
    if (pageIndex < storyPages.length - 1) {
      setPageIndex(pageIndex + 1);
      return;
    }

    // Otherwise, generate the next chapter
    setIsGeneratingNext(true);
    try {
      // Get content of the current page to use as context
      const currentContent = storyPages[pageIndex].content;

      const newPage = await generateStory(
        language, 
        level, 
        storyDescription, 
        storyStyle,
        currentContent // Pass previous context
      );

      setStoryPages(prev => [...prev, newPage]);
      setPageIndex(prev => prev + 1);
    } catch (err: any) {
      console.error("Failed to generate next page", err);
      // Optional: Show a toast or alert, but we'll keep the current page visible
      alert("Failed to generate the next chapter. Please try again.");
    } finally {
      setIsGeneratingNext(false);
    }
  };

  // Helper to determine what to display
  const currentStory = pageIndex >= 0 && storyPages.length > pageIndex ? storyPages[pageIndex] : null;

  return (
    <div className="min-h-screen bg-gray-50 px-4 py-8 sm:px-6 lg:px-8">
      {/* Navbar / Header */}
      <header className="mx-auto max-w-7xl mb-10 text-center">
        <div className="flex items-center justify-center space-x-3 mb-2">
            <div className="p-2 bg-indigo-600 rounded-lg text-white">
                <BookMarked className="w-8 h-8" />
            </div>
            <h1 className="text-3xl font-bold tracking-tight text-gray-900 sm:text-4xl">
            LinguaTale
            </h1>
        </div>
        <p className="text-lg text-gray-600 max-w-2xl mx-auto">
          AI-powered stories tailored to your exact language proficiency level.
        </p>
      </header>

      <main className="mx-auto max-w-7xl">
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12">

          {/* Left Column: Controls */}
          <div className="lg:col-span-4">
            <div className="sticky top-8 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-gray-900/5">
              <div className="bg-gradient-to-r from-indigo-500 to-purple-600 px-6 py-4">
                <h2 className="flex items-center text-lg font-semibold text-white">
                  <Sparkles className="mr-2 h-5 w-5" />
                  Story Settings
                </h2>
              </div>

              <div className="space-y-6 p-6">
                <Selector<Language> 
                  label="Target Language" 
                  value={language} 
                  options={LANGUAGES} 
                  onChange={setLanguage}
                  disabled={generation.isLoading || isGeneratingNext}
                />

                <Selector<CEFRLevel> 
                  label="Language Level" 
                  value={level} 
                  options={LEVELS} 
                  onChange={setLevel}
                  disabled={generation.isLoading || isGeneratingNext}
                  getLabel={(opt) => LEVEL_DESCRIPTIONS[opt]}
                />

                <Selector<StoryStyle> 
                  label="Story Style" 
                  value={storyStyle} 
                  options={STORY_STYLES} 
                  onChange={setStoryStyle}
                  disabled={generation.isLoading || isGeneratingNext}
                />

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-gray-700">
                    Story Description
                  </label>
                  <textarea
                    value={storyDescription}
                    onChange={(e) => setStoryDescription(e.target.value)}
                    placeholder="Describe your story topics (e.g., shopping, lost wallet, police station)..."
                    className="w-full h-32 resize-none rounded-lg border border-gray-300 bg-white text-gray-900 px-4 py-3 shadow-sm focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 disabled:bg-gray-100 placeholder:text-gray-400"
                    disabled={generation.isLoading || isGeneratingNext}
                  />

                  {/* Tag Cloud */}
                  <div className="pt-2">
                    <div className="flex items-center gap-1 mb-2 text-xs font-medium text-gray-500 uppercase tracking-wide">
                        <Tag className="w-3 h-3" />
                        <span>Suggested Topics</span>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {SUGGESTED_TOPICS.map((tag) => (
                        <button
                          key={tag}
                          onClick={() => handleTagClick(tag)}
                          disabled={generation.isLoading || isGeneratingNext}
                          className="px-3 py-1 text-xs font-medium text-indigo-700 bg-indigo-50 rounded-full border border-indigo-100 hover:bg-indigo-100 hover:border-indigo-200 transition-colors active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                          + {tag}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="pt-2">
                  <button
                    onClick={handleGenerate}
                    disabled={generation.isLoading || isGeneratingNext || !storyDescription.trim()}
                    className="flex w-full items-center justify-center rounded-xl bg-indigo-600 px-4 py-4 font-bold text-white shadow-md transition-all hover:bg-indigo-700 hover:shadow-lg hover:shadow-indigo-500/20 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:bg-gray-300 disabled:shadow-none"
                  >
                    {generation.isLoading ? "Starting Story..." : (
                        <>
                            New Story <Send className="ml-2 h-4 w-4" />
                        </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Right Column: Display */}
          <div className="flex flex-col items-center lg:col-span-8">
            {generation.isLoading && <LoadingState message="Creating your first chapter..." />}

            {generation.error && (
              <div className="w-full rounded-xl border border-red-200 bg-red-50 p-4 text-center text-red-700">
                <p className="font-medium">Error generating story</p>
                <p className="text-sm">{generation.error}</p>
              </div>
            )}

            {!generation.isLoading && !generation.error && !currentStory && (
              <div className="flex h-96 w-full flex-col items-center justify-center rounded-3xl border-2 border-dashed border-gray-200 bg-white/50 text-center">
                <div className="mb-4 rounded-full bg-indigo-50 p-4">
                  <BookMarked className="h-10 w-10 text-indigo-200" />
                </div>
                <h3 className="text-xl font-medium text-gray-500">Ready to read?</h3>
                <p className="mt-1 text-gray-400">Describe your story topics and click New Story.</p>
              </div>
            )}

            {currentStory && (
              <StoryDisplay 
                story={currentStory} 
                language={language}
                level={level}
                onNextPage={handleNextPage}
                onPrevPage={handlePrevPage}
                canGoNext={true} // Always allow trying for next page
                canGoPrev={pageIndex > 0}
                hasNextPageInHistory={pageIndex < storyPages.length - 1}
                isGeneratingNext={isGeneratingNext}
                currentPage={pageIndex + 1}
              />
            )}
          </div>

        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { BookOpen, Languages, HelpCircle, CheckCircle2, XCircle, ArrowLeft, ArrowRight, Loader2 } from 'lucide-react';
import { StoryResponse } from '../types';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  level: string;
  onNextPage: () => void;
  onPrevPage: () => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  hasNextPageInHistory: boolean;
  isGeneratingNext: boolean;
  currentPage: number;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
}

// Parses a single string (paragraph) into segments of text and interactive vocab words
const parseParagraph = (text: string): TextSegment[] => {
  const regex = /\{([^|]+)\|([^}]+)\}/g;
  const segments: TextSegment[] = [];
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      segments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    segments.push({
      type: 'vocab',
      content: match[1].trim(),
      translation: match[2].trim()
    });

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    segments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  return segments;
};

export const StoryDisplay: React.FC<StoryDisplayProps> = ({ 
  story, 
  language, 
  level,
  onNextPage,
  onPrevPage,
  canGoPrev,
  canGoNext,
  hasNextPageInHistory,
  isGeneratingNext,
  currentPage
}) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, string>>({});

  // Reset local state when story changes (pagination)
  useEffect(() => {
    setShowTranslation(false);
    setActiveTooltipId(null);
    setQuizAnswers({});
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [story]);

  // Split story content into paragraphs
  const paragraphs = useMemo(() => {
    if (!story.content) return [];

    // Handle edge case where model produces literal "\n" string characters instead of control characters
    const normalizedContent = story.content.replace(/\\n/g, '\n');

    // Split by one or more newline characters to ensure distinct paragraphs are created
    return normalizedContent.split(/\n+/).filter(p => p.trim().length > 0);
  }, [story.content]);

  const handleBackgroundClick = () => {
    setActiveTooltipId(null);
  };

  const handleQuizOptionClick = (questionIndex: number, option: string) => {
    setQuizAnswers(prev => ({
      ...prev,
      [questionIndex]: option
    }));
  };

  return (
    <div className="animate-fade-in-up w-full max-w-3xl overflow-hidden rounded-2xl bg-white shadow-xl ring-1 ring-gray-900/5">
      {/* Header */}
      <div className="border-b border-gray-100 bg-indigo-600 px-6 py-4 text-white">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <BookOpen className="h-5 w-5" />
            <span className="font-medium opacity-90">{language} Story</span>
          </div>
          <div className="flex items-center gap-3">
             <span className="opacity-75 text-xs font-medium uppercase tracking-wider">Page {currentPage}</span>
             <span className="rounded-full bg-white/20 px-3 py-1 text-xs font-bold text-white">
                Level {level}
            </span>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="space-y-8 px-6 py-8 sm:px-8">

        {/* Story Section */}
        <section onClick={handleBackgroundClick}>
          <h2 className="mb-6 text-2xl font-bold text-gray-900 sm:text-3xl text-center">
            {story.title}
          </h2>

          <div className="prose prose-lg max-w-none text-gray-700">
            {paragraphs.map((paragraph, pIndex) => {
              const segments = parseParagraph(paragraph);

              return (
                <p key={pIndex} className="mb-6 leading-relaxed last:mb-0">
                  {segments.map((segment, sIndex) => {
                    if (segment.type === 'text') {
                      return <span key={sIndex}>{segment.content}</span>;
                    }

                    // Create a unique ID for this segment based on paragraph and segment index
                    const uniqueId = `${pIndex}-${sIndex}`;
                    const isOpen = activeTooltipId === uniqueId;

                    return (
                      <span key={sIndex} className="relative inline-block mx-0.5 align-baseline">
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveTooltipId(isOpen ? null : uniqueId);
                          }}
                          className={`
                            cursor-pointer rounded-sm border-b-2 font-semibold transition-colors outline-none
                            ${isOpen 
                              ? 'border-indigo-600 bg-indigo-50 text-indigo-900' 
                              : 'border-indigo-300 text-indigo-800 hover:bg-indigo-50'
                            }
                          `}
                        >
                          {segment.content}
                        </button>

                        {isOpen && (
                          <div className="absolute bottom-full left-1/2 mb-2 z-50 -translate-x-1/2">
                            <div className="animate-fade-in relative rounded-lg bg-gray-900 px-3 py-2 text-sm font-medium text-white shadow-xl">
                              <span className="whitespace-nowrap">{segment.translation}</span>
                              <div className="absolute top-full left-1/2 -ml-1.5 -mt-1 h-3 w-3 -translate-x-1/2 rotate-45 bg-gray-900"></div>
                            </div>
                          </div>
                        )}
                      </span>
                    );
                  })}
                </p>
              );
            })}
          </div>
        </section>

        {/* Pagination Controls */}
        <div className="flex items-center justify-between border-t border-gray-100 pt-6">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-white disabled:hover:text-gray-700"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>Previous Page</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className={`group flex items-center space-x-2 rounded-lg px-5 py-2 text-sm font-medium shadow-sm transition-all disabled:opacity-70 disabled:cursor-not-allowed disabled:shadow-none
                    ${!hasNextPageInHistory 
                        ? "bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-md" 
                        : "border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600"
                    }
                `}
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>Creating Next Page...</span>
                     </>
                ) : (
                    <>
                        <span>Next Page</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>

        {/* Translation Toggle */}
        <div className="flex justify-center border-t border-gray-100 pt-6">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-medium text-indigo-600 hover:text-indigo-800 focus:outline-none transition-colors"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? "Hide Full Translation" : "Show Full Translation"}</span>
            </button>
        </div>

        {/* Translation Section */}
        {showTranslation && (
            <div className="animate-fade-in rounded-xl bg-gray-50 p-6 text-gray-600 ring-1 ring-gray-900/5">
                <h3 className="mb-3 text-xs font-bold uppercase tracking-wider text-gray-400">English Translation</h3>
                <p className="whitespace-pre-line leading-relaxed">{story.englishTranslation}</p>
            </div>
        )}

        {/* Quiz Section */}
        <div className="mt-8 border-t border-gray-100 pt-8">
            <div className="flex items-center space-x-2 mb-6">
                <HelpCircle className="h-5 w-5 text-indigo-600" />
                <h3 className="text-xl font-bold text-gray-900">Comprehension Quiz</h3>
            </div>

            <div className="space-y-6">
              {story.quiz.map((item, index) => {
                const selectedAnswer = quizAnswers[index];
                const isCorrect = selectedAnswer === item.correctAnswer;
                const hasAnswered = selectedAnswer != null;

                return (
                  <div key={index} className="rounded-xl border border-gray-200 bg-gray-50/50 p-5 transition-all hover:bg-white hover:shadow-sm">
                    <p className="mb-4 font-medium text-gray-900">
                      <span className="mr-2 text-indigo-600">{index + 1}.</span>
                      {item.question}
                    </p>

                    <div className="space-y-2">
                      {item.options.map((option) => {
                        let buttonStyle = "border-gray-200 bg-white text-gray-700 hover:border-indigo-300 hover:bg-indigo-50";
                        let icon = null;

                        if (hasAnswered) {
                           if (option === item.correctAnswer) {
                             buttonStyle = "border-green-500 bg-green-50 text-green-700 ring-1 ring-green-500";
                             icon = <CheckCircle2 className="h-4 w-4 text-green-600" />;
                           } else if (option === selectedAnswer) {
                             buttonStyle = "border-red-300 bg-red-50 text-red-700";
                             icon = <XCircle className="h-4 w-4 text-red-500" />;
                           } else {
                             buttonStyle = "border-gray-200 bg-gray-50 text-gray-400 opacity-60";
                           }
                        }

                        return (
                          <button
                            key={option}
                            onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                            disabled={hasAnswered}
                            className={`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left text-sm font-medium transition-all ${buttonStyle} ${!hasAnswered ? 'active:scale-[0.99]' : ''}`}
                          >
                            <span>{option}</span>
                            {icon}
                          </button>
                        );
                      })}
                    </div>

                    {hasAnswered && isCorrect && (
                      <p className="mt-2 text-xs font-bold text-green-600 animate-fade-in">Correct!</p>
                    )}
                    {hasAnswered && !isCorrect && (
                      <p className="mt-2 text-xs font-bold text-red-500 animate-fade-in">Incorrect, the answer was {item.correctAnswer}</p>
                    )}
                  </div>
                );
              })}
            </div>
        </div>
      </div>
    </div>
  );
};

