import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CEFRLevel, Language, StoryResponse, StoryStyle } from "../types";

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    title: {
      type: Type.STRING,
      description: "The title of the story (or chapter) in the target language."
    },
    content: {
      type: Type.STRING,
      description: "The main body of the story in the target language. Use \\n\\n to separate paragraphs."
    },
    englishTranslation: {
      type: Type.STRING,
      description: "A full English translation of the story."
    },
    quiz: {
      type: Type.ARRAY,
      description: "A reading comprehension quiz with 3 questions in the TARGET LANGUAGE.",
      items: {
        type: Type.OBJECT,
        properties: {
          question: { type: Type.STRING, description: "The question in the TARGET LANGUAGE (not English)." },
          options: { 
            type: Type.ARRAY, 
            description: "3 possible answers in the TARGET LANGUAGE.",
            items: { type: Type.STRING } 
          },
          correctAnswer: { type: Type.STRING, description: "The correct answer string, which must match one of the options." }
        },
        required: ["question", "options", "correctAnswer"]
      }
    }
  },
  required: ["title", "content", "englishTranslation", "quiz"]
};

// Helper to get specific vocabulary count based on level
const getVocabCount = (level: CEFRLevel): string => {
  if (level.startsWith("A1")) return "25-30"; // Maximum support for beginners
  if (level.startsWith("A2")) return "20-25";
  if (level.startsWith("B1")) return "15-20";
  if (level.startsWith("B2")) return "10-15";
  return "5-10"; // Minimal support for advanced
};

// Helper to get strict grammatical and structural constraints
const getLevelConstraints = (level: CEFRLevel): string => {
  switch (level) {
    case "A1.1":
      return `
        STRICT A1.1 RULES (Absolute Beginner):
        - Tense: Use ONLY Present Simple tense. NO Past or Future.
        - Sentence Structure: Extremely simple Subject-Verb-Object (SVO) only.
        - Length: Sentences must be very short (maximum 6-8 words).
        - Vocabulary: Use ONLY the most frequent 300 words (family, colors, numbers, basic verbs like 'is', 'has', 'go').
        - Connectors: NONE or only very basic 'and'.
        - NO relative clauses, NO compound sentences, NO idioms.
      `;
    case "A1.2":
      return `
        STRICT A1.2 RULES (Beginner):
        - Tense: Mostly Present Simple. Very frequent Past Simple verbs allowed (e.g., 'was', 'went').
        - Sentence Structure: Simple SVO.
        - Vocabulary: Top 500 frequent words.
        - Connectors: 'And', 'But'.
        - NO complex subordination.
      `;
    case "A1.3":
      return `
        STRICT A1.3 RULES (Elementary):
        - Tense: Present Simple and Simple Past. Introduction of 'Going to' for future.
        - Sentence Structure: Can join two simple clauses.
        - Vocabulary: Top 800 words (daily routines, hobbies).
      `;
    case "A2.1":
      return `
        STRICT A2.1 RULES (High Elementary):
        - Grammar: Past Simple, simple Future. Adjectives and adverbs of frequency.
        - Structure: Sentences can be slightly longer but must remain straightforward.
        - Topics: Immediate relevance (shopping, geography, work).
      `;
    case "A2.2":
      return `
        STRICT A2.2 RULES (Pre-Intermediate):
        - Grammar: Present Perfect (if applicable), Modal verbs (can, must, should).
        - Structure: basic subordinate clauses (because, when).
      `;
    case "B1.1":
    case "B1.2":
      return `
        STRICT B1 RULES (Intermediate):
        - Grammar: Connected text. All standard tenses used correctly.
        - Structure: Complex sentences allowed.
        - Vocabulary: Standard conversational vocabulary.
      `;
    case "B2.1":
    case "B2.2":
      return `
        STRICT B2 RULES (Upper Intermediate):
        - Grammar: Complex structures, passive voice, conditionals.
        - Vocabulary: Broad range, ability to discuss abstract ideas.
      `;
    case "C1-C2":
      return `
        STRICT C1/C2 RULES (Advanced):
        - Native-like complexity.
        - Use idioms, nuance, and implicit meaning.
        - Extensive vocabulary.
      `;
    default:
      return "Standard grammar rules.";
  }
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string,
  style: StoryStyle,
  previousContext?: string
): Promise<StoryResponse> => {

  const vocabCount = getVocabCount(level);
  const strictLevelConstraints = getLevelConstraints(level);

  // Language specific constraints (keep existing logic)
  let languageConstraints = "";
  if (language === "Finnish") {
    if (level.startsWith("A1")) {
      languageConstraints += " CRITICAL FINNISH RULE: Use mostly Nominative, Genitive, and Partitive cases. STRICTLY AVOID complex cases like Translative or Essive. Use simple Present tense.";
    } else if (level.startsWith("A2")) {
      languageConstraints += " CRITICAL FINNISH RULE: Introduce local cases (Inessive, Elative, Illative, Adessive, Ablative, Allative) sparingly. Keep sentence structure SVO where possible.";
    }
  }

  let taskDescription = "Task: Write a short story strictly adhering to the requested proficiency level.";
  let contentContext = "";

  if (previousContext) {
    taskDescription = "Task: Write the NEXT PART (continuation) of the story provided below. Keep the same characters, setting, and flow. Do NOT repeat the previous text.";
    contentContext = `
    PREVIOUS STORY CONTEXT (Do not repeat this, continue from here):
    "${previousContext.slice(-1500)}"
    `;
  }

  const prompt = `
    Role: You are an expert CEFR language teacher creating reading material.
    ${taskDescription}

    Parameters:
    - Target Language: ${language}
    - Level: ${level}
    - Topic/Keywords: ${topic}
    - Style: ${style}
    ${contentContext}

    STRICT LINGUISTIC CONSTRAINTS (DO NOT IGNORE):
    ${strictLevelConstraints}
    ${languageConstraints}

    If the story is too difficult for a student at level ${level}, you have FAILED the task. 
    Prioritize simplicity and readability over plot complexity for levels A1-A2.

    Content Structure:
    - Length: approx 300-500 words (adjusted for level complexity).
    - Paragraphs: 3-5 clear paragraphs separated by \\n\\n.
    - ENDING: Do NOT finish the story with a definitive ending like "The End". Write the story assuming it can continue to the next page. Keep the narrative flow open for a sequel/next chapter.

    Interactive Vocabulary:
    - Identify EXACTLY ${vocabCount} key words/phrases suitable for learning at this level.
    - Embed English translations strictly using this format: {inflected_word|english_translation}

    CRITICAL GRAMMAR RULE FOR EMBEDDED WORDS:
    - The text inside the curly braces (the left side before the |) MUST be the actual word used in the sentence, preserving all necessary inflections, cases, and conjugations.
    - DO NOT replace the inflected word with its basic/dictionary form. The sentence grammar must remain perfect.
    - DO NOT break compound words.

    Incorrect Example (Finnish): "Hän istui {tuoli|chair}." (Wrong: 'tuoli' does not fit the sentence structure).
    Correct Example (Finnish): "Hän istui {tuolilla|chair}." (Right: 'tuolilla' is the correct case).

    Quiz Requirement:
    - Create 3 reading comprehension questions based ONLY on this new part of the story.
    - CRITICAL: The questions and the answer options MUST BE IN ${language.toUpperCase()} (The Target Language).
    - Do NOT write the quiz in English.

    Output Format:
    Return valid JSON matching the schema:
    {
      "title": "Title (or Chapter Name) in ${language}",
      "content": "Story text...",
      "englishTranslation": "Full English translation...",
      "quiz": [
        { "question": "Question in ${language}?", "options": ["Option A", "Option B", "Option C"], "correctAnswer": "Option A" }
      ]
    }
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.6, 
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate story. Please verify your API key and try again.");
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { BookOpen, Languages, HelpCircle, CheckCircle2, XCircle, ArrowLeft, ArrowRight, Loader2 } from 'lucide-react';
import { StoryResponse } from '../types';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  level: string;
  onNextPage: () => void;
  onPrevPage: () => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  hasNextPageInHistory: boolean;
  isGeneratingNext: boolean;
  currentPage: number;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
}

// Parses a single string (paragraph) into segments of text and interactive vocab words
const parseParagraph = (text: string): TextSegment[] => {
  const regex = /\{([^|]+)\|([^}]+)\}/g;
  const segments: TextSegment[] = [];
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      segments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    segments.push({
      type: 'vocab',
      content: match[1].trim(),
      translation: match[2].trim()
    });

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    segments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  return segments;
};

export const StoryDisplay: React.FC<StoryDisplayProps> = ({ 
  story, 
  language, 
  level,
  onNextPage,
  onPrevPage,
  canGoPrev,
  canGoNext,
  hasNextPageInHistory,
  isGeneratingNext,
  currentPage
}) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, string>>({});

  // Reset local state when story changes (pagination)
  useEffect(() => {
    setShowTranslation(false);
    setActiveTooltipId(null);
    setQuizAnswers({});
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [story]);

  // Split story content into paragraphs
  const paragraphs = useMemo(() => {
    if (!story.content) return [];

    // Handle edge case where model produces literal "\n" string characters instead of control characters
    const normalizedContent = story.content.replace(/\\n/g, '\n');

    // Split by one or more newline characters to ensure distinct paragraphs are created
    return normalizedContent.split(/\n+/).filter(p => p.trim().length > 0);
  }, [story.content]);

  const handleBackgroundClick = () => {
    setActiveTooltipId(null);
  };

  const handleQuizOptionClick = (questionIndex: number, option: string) => {
    setQuizAnswers(prev => ({
      ...prev,
      [questionIndex]: option
    }));
  };

  return (
    <div className="animate-fade-in-up w-full max-w-3xl overflow-hidden rounded-2xl bg-white shadow-xl ring-1 ring-gray-900/5">
      {/* Header */}
      <div className="border-b border-gray-100 bg-indigo-600 px-6 py-4 text-white">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <BookOpen className="h-5 w-5" />
            <span className="font-medium opacity-90">{language} Story</span>
          </div>
          <div className="flex items-center gap-3">
             <span className="opacity-75 text-xs font-medium uppercase tracking-wider">Page {currentPage}</span>
             <span className="rounded-full bg-white/20 px-3 py-1 text-xs font-bold text-white">
                Level {level}
            </span>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="space-y-8 px-6 py-8 sm:px-8">

        {/* Story Section */}
        <section onClick={handleBackgroundClick}>
          <h2 className="mb-6 text-2xl font-bold text-gray-900 sm:text-3xl text-center">
            {story.title}
          </h2>

          <div className="prose prose-lg max-w-none text-gray-700">
            {paragraphs.map((paragraph, pIndex) => {
              const segments = parseParagraph(paragraph);

              return (
                <p key={pIndex} className="mb-6 leading-relaxed last:mb-0">
                  {segments.map((segment, sIndex) => {
                    if (segment.type === 'text') {
                      return <span key={sIndex}>{segment.content}</span>;
                    }

                    // Create a unique ID for this segment based on paragraph and segment index
                    const uniqueId = `${pIndex}-${sIndex}`;
                    const isOpen = activeTooltipId === uniqueId;

                    return (
                      <span key={sIndex} className="relative group">
                        <span
                          role="button"
                          tabIndex={0}
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveTooltipId(isOpen ? null : uniqueId);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                              e.preventDefault();
                              e.stopPropagation();
                              setActiveTooltipId(isOpen ? null : uniqueId);
                            }
                          }}
                          className={`
                            cursor-pointer rounded-sm border-b-2 font-semibold transition-colors outline-none px-0.5
                            ${isOpen 
                              ? 'border-indigo-600 bg-indigo-50 text-indigo-900' 
                              : 'border-indigo-300 text-indigo-800 hover:bg-indigo-50'
                            }
                          `}
                        >
                          {segment.content}
                        </span>

                        {isOpen && (
                          <div className="absolute bottom-full left-1/2 mb-2 z-50 -translate-x-1/2">
                            <div className="animate-fade-in relative rounded-lg bg-gray-900 px-3 py-2 text-sm font-medium text-white shadow-xl">
                              <span className="whitespace-nowrap">{segment.translation}</span>
                              <div className="absolute top-full left-1/2 -ml-1.5 -mt-1 h-3 w-3 -translate-x-1/2 rotate-45 bg-gray-900"></div>
                            </div>
                          </div>
                        )}
                      </span>
                    );
                  })}
                </p>
              );
            })}
          </div>
        </section>

        {/* Pagination Controls */}
        <div className="flex items-center justify-between border-t border-gray-100 pt-6">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-white disabled:hover:text-gray-700"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>Previous Page</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className={`group flex items-center space-x-2 rounded-lg px-5 py-2 text-sm font-medium shadow-sm transition-all disabled:opacity-70 disabled:cursor-not-allowed disabled:shadow-none
                    ${!hasNextPageInHistory 
                        ? "bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-md" 
                        : "border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600"
                    }
                `}
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>Creating Next Page...</span>
                     </>
                ) : (
                    <>
                        <span>Next Page</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>

        {/* Translation Toggle */}
        <div className="flex justify-center border-t border-gray-100 pt-6">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-medium text-indigo-600 hover:text-indigo-800 focus:outline-none transition-colors"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? "Hide Full Translation" : "Show Full Translation"}</span>
            </button>
        </div>

        {/* Translation Section */}
        {showTranslation && (
            <div className="animate-fade-in rounded-xl bg-gray-50 p-6 text-gray-600 ring-1 ring-gray-900/5">
                <h3 className="mb-3 text-xs font-bold uppercase tracking-wider text-gray-400">English Translation</h3>
                <p className="whitespace-pre-line leading-relaxed">{story.englishTranslation}</p>
            </div>
        )}

        {/* Quiz Section */}
        <div className="mt-8 border-t border-gray-100 pt-8">
            <div className="flex items-center space-x-2 mb-6">
                <HelpCircle className="h-5 w-5 text-indigo-600" />
                <h3 className="text-xl font-bold text-gray-900">Comprehension Quiz</h3>
            </div>

            <div className="space-y-6">
              {story.quiz.map((item, index) => {
                const selectedAnswer = quizAnswers[index];
                const isCorrect = selectedAnswer === item.correctAnswer;
                const hasAnswered = selectedAnswer != null;

                return (
                  <div key={index} className="rounded-xl border border-gray-200 bg-gray-50/50 p-5 transition-all hover:bg-white hover:shadow-sm">
                    <p className="mb-4 font-medium text-gray-900">
                      <span className="mr-2 text-indigo-600">{index + 1}.</span>
                      {item.question}
                    </p>

                    <div className="space-y-2">
                      {item.options.map((option) => {
                        let buttonStyle = "border-gray-200 bg-white text-gray-700 hover:border-indigo-300 hover:bg-indigo-50";
                        let icon = null;

                        if (hasAnswered) {
                           if (option === item.correctAnswer) {
                             buttonStyle = "border-green-500 bg-green-50 text-green-700 ring-1 ring-green-500";
                             icon = <CheckCircle2 className="h-4 w-4 text-green-600" />;
                           } else if (option === selectedAnswer) {
                             buttonStyle = "border-red-300 bg-red-50 text-red-700";
                             icon = <XCircle className="h-4 w-4 text-red-500" />;
                           } else {
                             buttonStyle = "border-gray-200 bg-gray-50 text-gray-400 opacity-60";
                           }
                        }

                        return (
                          <button
                            key={option}
                            onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                            disabled={hasAnswered}
                            className={`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left text-sm font-medium transition-all ${buttonStyle} ${!hasAnswered ? 'active:scale-[0.99]' : ''}`}
                          >
                            <span>{option}</span>
                            {icon}
                          </button>
                        );
                      })}
                    </div>

                    {hasAnswered && isCorrect && (
                      <p className="mt-2 text-xs font-bold text-green-600 animate-fade-in">Correct!</p>
                    )}
                    {hasAnswered && !isCorrect && (
                      <p className="mt-2 text-xs font-bold text-red-500 animate-fade-in">Incorrect, the answer was {item.correctAnswer}</p>
                    )}
                  </div>
                );
              })}
            </div>
        </div>
      </div>
    </div>
  );
};

