                  disabled={generation.isLoading || isGeneratingNext}
                />

                <Selector<CEFRLevel> 
                  label={t.languageLevel}
                  value={level} 
                  options={LEVELS} 
                  onChange={setLevel}
                  disabled={generation.isLoading || isGeneratingNext}
                  getLabel={(opt) => levelDescriptions[opt]}
                />

                <Selector<StoryStyle> 
                  label={t.storyStyle} 
                  value={storyStyle} 
                  options={STORY_STYLES} 
