import React, { useState, useMemo, useEffect } from 'react';
import { BookOpen, Languages, HelpCircle, CheckCircle2, XCircle, ArrowLeft, ArrowRight, Loader2 } from 'lucide-react';
import { StoryResponse } from '../types';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  styleLabel: string;
  level: string;
  onNextPage: () => void;
  onPrevPage: () => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  hasNextPageInHistory: boolean;
  isGeneratingNext: boolean;
  currentPage: number;
  translations: Record<string, string>;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
}

// Parses a single string (paragraph) into segments of text and interactive vocab words
const parseParagraph = (text: string): TextSegment[] => {
  const regex = /\{([^|]+)\|([^}]+)\}/g;
  const segments: TextSegment[] = [];
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      segments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    segments.push({
      type: 'vocab',
      content: match[1].trim(),
      translation: match[2].trim()
    });

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    segments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  return segments;
};

export const StoryDisplay: React.FC<StoryDisplayProps> = ({ 
  story, 
  language, 
  styleLabel,
  level,
  onNextPage,
  onPrevPage,
  canGoPrev,
  canGoNext,
  hasNextPageInHistory,
  isGeneratingNext,
  currentPage,
  translations
}) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, string>>({});

  // Reset local state when story changes (pagination)
  useEffect(() => {
    setShowTranslation(false);
    setActiveTooltipId(null);
    setQuizAnswers({});
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [story]);

  // Split story content into paragraphs
  const paragraphs = useMemo(() => {
    if (!story.content) return [];

    // Handle edge case where model produces literal "\n" string characters instead of control characters
    const normalizedContent = story.content.replace(/\\n/g, '\n');

    // Split by one or more newline characters to ensure distinct paragraphs are created
    return normalizedContent.split(/\n+/).filter(p => p.trim().length > 0);
  }, [story.content]);

  const handleBackgroundClick = () => {
    setActiveTooltipId(null);
  };

  const handleQuizOptionClick = (questionIndex: number, option: string) => {
    setQuizAnswers(prev => ({
      ...prev,
      [questionIndex]: option
    }));
  };

  return (
    <div className="animate-fade-in-up w-full max-w-3xl overflow-hidden rounded-2xl bg-white shadow-xl ring-1 ring-gray-900/5">
      {/* Header */}
      <div className="border-b border-gray-100 bg-indigo-600 px-6 py-4 text-white">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <BookOpen className="h-5 w-5" />
            <span className="font-medium opacity-90">{language} {styleLabel}</span>
          </div>
          <div className="flex items-center gap-3">
             <span className="opacity-75 text-xs font-medium uppercase tracking-wider">{translations.page} {currentPage}</span>
             <span className="rounded-full bg-white/20 px-3 py-1 text-xs font-bold text-white">
                {translations.level} {level}
            </span>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="space-y-8 px-6 py-8 sm:px-8">

        {/* Story Section */}
        <section onClick={handleBackgroundClick}>
          <h2 className="mb-6 text-2xl font-bold text-gray-900 sm:text-3xl text-center">
            {story.title}
          </h2>

          <div className="prose prose-lg max-w-none text-gray-700">
            {paragraphs.map((paragraph, pIndex) => {
              const segments = parseParagraph(paragraph);

              return (
                <p key={pIndex} className="mb-6 leading-relaxed last:mb-0">
                  {segments.map((segment, sIndex) => {
                    if (segment.type === 'text') {
                      return <span key={sIndex}>{segment.content}</span>;
                    }

                    // Create a unique ID for this segment based on paragraph and segment index
                    const uniqueId = `${pIndex}-${sIndex}`;
                    const isOpen = activeTooltipId === uniqueId;

                    return (
                      <span key={sIndex} className="relative group">
                        <span
                          role="button"
                          tabIndex={0}
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveTooltipId(isOpen ? null : uniqueId);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                              e.preventDefault();
                              e.stopPropagation();
                              setActiveTooltipId(isOpen ? null : uniqueId);
                            }
                          }}
                          className={`
                            cursor-pointer rounded-sm border-b-2 font-semibold transition-colors outline-none px-0.5
                            ${isOpen 
                              ? 'border-indigo-600 bg-indigo-50 text-indigo-900' 
                              : 'border-indigo-300 text-indigo-800 hover:bg-indigo-50'
                            }
                          `}
                        >
                          {segment.content}
                        </span>

                        {isOpen && (
                          <div className="absolute bottom-full left-1/2 mb-2 z-50 -translate-x-1/2">
                            <div className="animate-fade-in relative rounded-lg bg-gray-900 px-3 py-2 text-sm font-medium text-white shadow-xl">
                              <span className="whitespace-nowrap">{segment.translation}</span>
                              <div className="absolute top-full left-1/2 -ml-1.5 -mt-1 h-3 w-3 -translate-x-1/2 rotate-45 bg-gray-900"></div>
                            </div>
                          </div>
                        )}
                      </span>
                    );
                  })}
                </p>
              );
            })}
          </div>
        </section>

        {/* Pagination Controls */}
        <div className="flex items-center justify-between border-t border-gray-100 pt-6">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-white disabled:hover:text-gray-700"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>{translations.previousPage}</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className={`group flex items-center space-x-2 rounded-lg px-5 py-2 text-sm font-medium shadow-sm transition-all disabled:opacity-70 disabled:cursor-not-allowed disabled:shadow-none
                    ${!hasNextPageInHistory 
                        ? "bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-md" 
                        : "border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600"
                    }
                `}
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>{translations.creatingNextPage}</span>
                     </>
                ) : (
                    <>
                        <span>{translations.nextPage}</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>

        {/* Translation Toggle */}
        <div className="flex justify-center border-t border-gray-100 pt-6">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-medium text-indigo-600 hover:text-indigo-800 focus:outline-none transition-colors"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? translations.hideTranslation : translations.showTranslation}</span>
            </button>
        </div>

        {/* Translation Section */}
        {showTranslation && (
            <div className="animate-fade-in rounded-xl bg-gray-50 p-6 text-gray-600 ring-1 ring-gray-900/5">
                <h3 className="mb-3 text-xs font-bold uppercase tracking-wider text-gray-400">{translations.translationTitle}</h3>
                <p className="whitespace-pre-line leading-relaxed">{story.englishTranslation}</p>
            </div>
        )}

        {/* Quiz Section */}
        <div className="mt-8 border-t border-gray-100 pt-8">
            <div className="flex items-center space-x-2 mb-6">
                <HelpCircle className="h-5 w-5 text-indigo-600" />
                <h3 className="text-xl font-bold text-gray-900">{translations.comprehensionQuiz}</h3>
            </div>

            <div className="space-y-6">
              {story.quiz.map((item, index) => {
                const selectedAnswer = quizAnswers[index];
                const isCorrect = selectedAnswer === item.correctAnswer;
                const hasAnswered = selectedAnswer != null;

                return (
                  <div key={index} className="rounded-xl border border-gray-200 bg-gray-50/50 p-5 transition-all hover:bg-white hover:shadow-sm">
                    <p className="mb-4 font-medium text-gray-900">
                      <span className="mr-2 text-indigo-600">{index + 1}.</span>
                      {item.question}
                    </p>

                    <div className="space-y-2">
                      {item.options.map((option) => {
                        let buttonStyle = "border-gray-200 bg-white text-gray-700 hover:border-indigo-300 hover:bg-indigo-50";
                        let icon = null;

                        if (hasAnswered) {
                           if (option === item.correctAnswer) {
                             buttonStyle = "border-green-500 bg-green-50 text-green-700 ring-1 ring-green-500";
                             icon = <CheckCircle2 className="h-4 w-4 text-green-600" />;
                           } else if (option === selectedAnswer) {
                             buttonStyle = "border-red-300 bg-red-50 text-red-700";
                             icon = <XCircle className="h-4 w-4 text-red-500" />;
                           } else {
                             buttonStyle = "border-gray-200 bg-gray-50 text-gray-400 opacity-60";
                           }
                        }

                        return (
                          <button
                            key={option}
                            onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                            disabled={hasAnswered}
                            className={`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left text-sm font-medium transition-all ${buttonStyle} ${!hasAnswered ? 'active:scale-[0.99]' : ''}`}
                          >
                            <span>{option}</span>
                            {icon}
                          </button>
                        );
                      })}
                    </div>

                    {hasAnswered && isCorrect && (
                      <p className="mt-2 text-xs font-bold text-green-600 animate-fade-in">{translations.correct}</p>
                    )}
                    {hasAnswered && !isCorrect && (
                      <p className="mt-2 text-xs font-bold text-red-500 animate-fade-in">{translations.incorrect} {item.correctAnswer}</p>
                    )}
                  </div>
                );
              })}
            </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CEFRLevel, Language, StoryResponse, StoryStyle, AppLanguage } from "../types";

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    title: {
      type: Type.STRING,
      description: "The title of the story (or chapter) in the target language."
    },
    content: {
      type: Type.STRING,
      description: "The main body of the story in the target language. Use \\n\\n to separate paragraphs."
    },
    englishTranslation: {
      type: Type.STRING,
      description: "A full translation of the story in the requested OUTPUT LANGUAGE."
    },
    quiz: {
      type: Type.ARRAY,
      description: "A reading comprehension quiz with 3 questions in the TARGET LANGUAGE.",
      items: {
        type: Type.OBJECT,
        properties: {
          question: { type: Type.STRING, description: "The question in the TARGET LANGUAGE (not English)." },
          options: { 
            type: Type.ARRAY, 
            description: "3 possible answers in the TARGET LANGUAGE.",
            items: { type: Type.STRING } 
          },
          correctAnswer: { type: Type.STRING, description: "The correct answer string, which must match one of the options." }
        },
        required: ["question", "options", "correctAnswer"]
      }
    }
  },
  required: ["title", "content", "englishTranslation", "quiz"]
};

// Helper to get specific vocabulary count based on level
const getVocabCount = (level: CEFRLevel): string => {
  if (level.startsWith("A1")) return "15-20"; 
  if (level.startsWith("A2")) return "12-15";
  if (level.startsWith("B1")) return "10-12";
  if (level.startsWith("B2")) return "8-10";
  return "5-8"; 
};

// Helper to get strict grammatical and structural constraints
const getLevelConstraints = (level: CEFRLevel): string => {
  switch (level) {
    case "A1.1":
      return `
        CRITICAL: LEVEL A1.1 (ABSOLUTE BEGINNER) - EXTREMELY RESTRICTIVE
        1. TENSES: Use ONLY Present Simple (e.g., "It is", "She has"). ABSOLUTELY NO Past, NO Future, NO Continuous tenses.
        2. VERBS: Use only the top 50 most basic verbs (be, have, do, go, see, eat, drink, sleep, want, like).
        3. SYNTAX: Subject-Verb-Object (SVO) sentences ONLY. 
        4. CONNECTORS: Use ONLY "and". DO NOT USE "but", "because", "so", "or".
        5. SENTENCE LENGTH: Max 5-7 words per sentence.
        6. TOPICS: Concrete, visible objects only.
      `;
    case "A1.2":
      return `
        CRITICAL: LEVEL A1.2 (BEGINNER)
        1. TENSES: Mostly Present Simple. Limited high-frequency Past Simple ('was', 'did', 'went').
        2. SYNTAX: Simple sentences. Basic questions (Who, What, Where).
        3. CONNECTORS: "and", "but", "or".
        4. SENTENCE LENGTH: Average 6-8 words.
      `;
    case "A1.3":
      return `
        CRITICAL: LEVEL A1.3 (ELEMENTARY)
        1. TENSES: Present Simple, Present Continuous, Simple Past, 'Going to' future.
        2. SYNTAX: Compound sentences allowed.
        3. CONNECTORS: "and", "but", "or", "because".
      `;
    case "A2.1":
      return `
        CRITICAL: LEVEL A2.1 (HIGH ELEMENTARY)
        1. TENSES: Past Simple (Narrative). Future with 'will'. Imperatives.
        2. SYNTAX: Comparatives and Superlatives. Adverbs of frequency.
        3. CONNECTORS: Sequencing words (first, next, then, finally).
      `;
    case "A2.2":
      return `
        CRITICAL: LEVEL A2.2 (PRE-INTERMEDIATE)
        1. TENSES: Present Perfect for experience. Modal verbs (must, should, have to).
        2. SYNTAX: Zero/First Conditional. Relative clauses with "who" or "which".
      `;
    case "B1.1":
      return `
        LEVEL B1.1 (INTERMEDIATE)
        1. TENSES: Past Continuous, Present Perfect with for/since.
        2. SYNTAX: Simple Passive voice. Basic reported speech.
        3. CONNECTORS: "although", "however", "so that".
      `;
    case "B1.2":
      return `
        LEVEL B1.2 (HIGH INTERMEDIATE)
        1. TENSES: Past Perfect. Used to. 
        2. SYNTAX: Second Conditional. 
      `;
    case "B2.1":
      return `
        LEVEL B2.1 (UPPER INTERMEDIATE)
        1. TENSES: Future Continuous. Present Perfect Continuous.
        2. SYNTAX: Third Conditional. Mixed Conditionals. 
      `;
    case "B2.2":
      return `
        LEVEL B2.2 (PRE-ADVANCED)
        1. TENSES: All tenses naturally.
        2. SYNTAX: Complex passive forms. Inversion.
      `;
    case "C1-C2":
      return `
        LEVEL C1/C2 (ADVANCED/MASTERY)
        - Nuance, idioms, cultural references, complex literary structures.
      `;
    default:
      return "Standard grammar rules.";
  }
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string,
  style: StoryStyle,
  outputLanguage: AppLanguage,
  previousContext?: string
): Promise<StoryResponse> => {

  const vocabCount = getVocabCount(level);
  const strictLevelConstraints = getLevelConstraints(level);

  let languageConstraints = "";
  if (language === "Finnish") {
    if (level === "A1.1") {
        languageConstraints += " FINNISH A1.1 SPECIFIC: Use ONLY Nominative and Partitive. No other cases.";
    } else if (level === "A1.2") {
        languageConstraints += " FINNISH A1.2 SPECIFIC: Add Genitive and basic Inessive (-ssa/ssä).";
    }
  }

  let taskDescription = "Task: Write a short story strictly adhering to the requested proficiency level.";
  let contentContext = "";

  if (previousContext) {
    taskDescription = "Task: Write the NEXT PART (continuation) of the story provided below. Keep the same characters and setting.";
    contentContext = `
    PREVIOUS STORY CONTEXT:
    "${previousContext.slice(-1000)}"
    `;
  }

  const prompt = `
    Role: You are a language teacher and CEFR compliance expert.

    GOAL: Generate a story in ${language} at EXACTLY level ${level}.

    PARAMETERS:
    - Target Language: ${language}
    - CEFR Level: ${level}
    - Topic: ${topic}
    - Style: ${style}
    - Support Language (for translations): ${outputLanguage}

    ${contentContext}

    STRICT GRAMMAR RULES FOR ${level}:
    ${strictLevelConstraints}
    ${languageConstraints}

    VOCABULARY HIGHLIGHTING STRATEGY:
    1. Select ${vocabCount} words to highlight using the format: {word|translation}
    2. LEVEL-AWARE SELECTION: 
       - NEVER highlight basic words from levels BELOW ${level} (e.g., if target is B1, do not highlight A1/A2 words like "house", "go", "eat").
       - FOCUS highlights on words that are precisely at ${level} difficulty.
       - IF you must use a word that is HIGHER than ${level} for narrative reasons, YOU MUST highlight it.
       - DO NOT highlight "function words" (articles, common pronouns, basic prepositions).
       - The word inside the braces MUST match the exact inflected form used in the text.

    FORMAT:
    - Return JSON matching the requested schema.
    - Content should be 200-400 words.
    - Title should be in ${language}.
    - EnglishTranslation should be the full story translated into ${outputLanguage}.
    - Quiz should be 3 questions in ${language} about the text.
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.2,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate story. Please verify your API key.");
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { BookOpen, Languages, HelpCircle, CheckCircle2, XCircle, ArrowLeft, ArrowRight, Loader2 } from 'lucide-react';
import { StoryResponse } from '../types';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  styleLabel: string;
  level: string;
  onNextPage: () => void;
  onPrevPage: () => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  hasNextPageInHistory: boolean;
  isGeneratingNext: boolean;
  currentPage: number;
  translations: Record<string, string>;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
}

/**
 * Robustly parses text into segments.
 * Handles {word|translation} format even with extra whitespace or minor AI mishaps.
 */
const parseParagraph = (text: string): TextSegment[] => {
  if (!text) return [];

  // Improved regex: Non-greedy, allows spaces around the pipe, avoids matching across multiple braces.
  const regex = /\{([^{}|]+?)\s*\|\s*([^{}|]+?)\}/g;
  const segments: TextSegment[] = [];
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    // 1. Text before the match
    if (match.index > lastIndex) {
      segments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    const word = match[1].trim();
    const translation = match[2].trim();

    // 2. The vocabulary match (only if both parts exist)
    if (word && translation) {
      segments.push({
        type: 'vocab',
        content: word,
        translation: translation
      });
    } else {
      // If malformed, treat as plain text to avoid losing content
      segments.push({
        type: 'text',
        content: match[0]
      });
    }

    lastIndex = regex.lastIndex;
  }

  // 3. Remaining text after last match
  if (lastIndex < text.length) {
    segments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  return segments;
};

export const StoryDisplay: React.FC<StoryDisplayProps> = ({ 
  story, 
  language, 
  styleLabel,
  level,
  onNextPage,
  onPrevPage,
  canGoPrev,
  canGoNext,
  hasNextPageInHistory,
  isGeneratingNext,
  currentPage,
  translations
}) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, string>>({});

  useEffect(() => {
    setShowTranslation(false);
    setActiveTooltipId(null);
    setQuizAnswers({});
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [story]);

  const paragraphs = useMemo(() => {
    if (!story.content) return [];
    const normalizedContent = story.content.replace(/\\n/g, '\n');
    return normalizedContent.split(/\n+/).filter(p => p.trim().length > 0);
  }, [story.content]);

  const handleBackgroundClick = () => {
    setActiveTooltipId(null);
  };

  const handleQuizOptionClick = (questionIndex: number, option: string) => {
    setQuizAnswers(prev => ({
      ...prev,
      [questionIndex]: option
    }));
  };

  return (
    <div className="animate-fade-in-up w-full max-w-3xl overflow-hidden rounded-2xl bg-white shadow-xl ring-1 ring-gray-900/5">
      {/* Header */}
      <div className="border-b border-gray-100 bg-indigo-600 px-6 py-4 text-white">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <BookOpen className="h-5 w-5" />
            <span className="font-medium opacity-90">{language} {styleLabel}</span>
          </div>
          <div className="flex items-center gap-3">
             <span className="opacity-75 text-xs font-medium uppercase tracking-wider">{translations.page} {currentPage}</span>
             <span className="rounded-full bg-white/20 px-3 py-1 text-xs font-bold text-white">
                {translations.level} {level}
            </span>
          </div>
        </div>
      </div>

      <div className="space-y-8 px-6 py-8 sm:px-8">
        {/* Story Section */}
        <section onClick={handleBackgroundClick}>
          <h2 className="mb-6 text-2xl font-bold text-gray-900 sm:text-3xl text-center">
            {story.title}
          </h2>

          <div className="prose prose-lg max-w-none text-gray-700">
            {paragraphs.map((paragraph, pIndex) => {
              const segments = parseParagraph(paragraph);

              return (
                <p key={pIndex} className="mb-6 leading-relaxed last:mb-0">
                  {segments.map((segment, sIndex) => {
                    if (segment.type === 'text') {
                      return <span key={sIndex}>{segment.content}</span>;
                    }

                    const uniqueId = `${pIndex}-${sIndex}`;
                    const isOpen = activeTooltipId === uniqueId;

                    return (
                      <span key={sIndex} className="relative inline-block group">
                        <span
                          role="button"
                          tabIndex={0}
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveTooltipId(isOpen ? null : uniqueId);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                              e.preventDefault();
                              e.stopPropagation();
                              setActiveTooltipId(isOpen ? null : uniqueId);
                            }
                          }}
                          className={`
                            cursor-pointer rounded-sm border-b-2 font-semibold transition-all outline-none px-0.5
                            ${isOpen 
                              ? 'border-indigo-600 bg-indigo-50 text-indigo-900' 
                              : 'border-indigo-300 text-indigo-800 hover:bg-indigo-50 hover:border-indigo-400'
                            }
                          `}
                        >
                          {segment.content}
                        </span>

                        {isOpen && (
                          <div className="absolute bottom-full left-1/2 mb-2 z-50 -translate-x-1/2">
                            <div className="animate-fade-in relative rounded-lg bg-gray-900 px-3 py-2 text-sm font-medium text-white shadow-xl whitespace-nowrap">
                              {segment.translation}
                              <div className="absolute top-full left-1/2 -ml-1.5 -mt-1 h-3 w-3 -translate-x-1/2 rotate-45 bg-gray-900"></div>
                            </div>
                          </div>
                        )}
                      </span>
                    );
                  })}
                </p>
              );
            })}
          </div>
        </section>

        {/* Pagination Controls */}
        <div className="flex items-center justify-between border-t border-gray-100 pt-6">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>{translations.previousPage}</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className={`group flex items-center space-x-2 rounded-lg px-5 py-2 text-sm font-medium shadow-sm transition-all disabled:opacity-70 disabled:cursor-not-allowed
                    ${!hasNextPageInHistory 
                        ? "bg-indigo-600 text-white hover:bg-indigo-700" 
                        : "border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600"
                    }
                `}
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>{translations.creatingNextPage}</span>
                     </>
                ) : (
                    <>
                        <span>{translations.nextPage}</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>

        <div className="flex justify-center border-t border-gray-100 pt-6">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-medium text-indigo-600 hover:text-indigo-800 focus:outline-none transition-colors"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? translations.hideTranslation : translations.showTranslation}</span>
            </button>
        </div>

        {showTranslation && (
            <div className="animate-fade-in rounded-xl bg-gray-50 p-6 text-gray-600 ring-1 ring-gray-900/5">
                <h3 className="mb-3 text-xs font-bold uppercase tracking-wider text-gray-400">{translations.translationTitle}</h3>
                <p className="whitespace-pre-line leading-relaxed">{story.englishTranslation}</p>
            </div>
        )}

        <div className="mt-8 border-t border-gray-100 pt-8">
            <div className="flex items-center space-x-2 mb-6">
                <HelpCircle className="h-5 w-5 text-indigo-600" />
                <h3 className="text-xl font-bold text-gray-900">{translations.comprehensionQuiz}</h3>
            </div>

            <div className="space-y-6">
              {story.quiz.map((item, index) => {
                const selectedAnswer = quizAnswers[index];
                const isCorrect = selectedAnswer === item.correctAnswer;
                const hasAnswered = selectedAnswer != null;

                return (
                  <div key={index} className="rounded-xl border border-gray-200 bg-gray-50/50 p-5 transition-all hover:bg-white hover:shadow-sm">
                    <p className="mb-4 font-medium text-gray-900">
                      <span className="mr-2 text-indigo-600">{index + 1}.</span>
                      {item.question}
                    </p>

                    <div className="space-y-2">
                      {item.options.map((option) => {
                        let buttonStyle = "border-gray-200 bg-white text-gray-700 hover:border-indigo-300 hover:bg-indigo-50";
                        let icon = null;

                        if (hasAnswered) {
                           if (option === item.correctAnswer) {
                             buttonStyle = "border-green-500 bg-green-50 text-green-700 ring-1 ring-green-500";
                             icon = <CheckCircle2 className="h-4 w-4 text-green-600" />;
                           } else if (option === selectedAnswer) {
                             buttonStyle = "border-red-300 bg-red-50 text-red-700";
                             icon = <XCircle className="h-4 w-4 text-red-500" />;
                           } else {
                             buttonStyle = "border-gray-200 bg-gray-50 text-gray-400 opacity-60";
                           }
                        }

                        return (
                          <button
                            key={option}
                            onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                            disabled={hasAnswered}
                            className={`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left text-sm font-medium transition-all ${buttonStyle}`}
                          >
                            <span>{option}</span>
                            {icon}
                          </button>
                        );
                      })}
                    </div>

                    {hasAnswered && (
                      <p className={`mt-2 text-xs font-bold animate-fade-in ${isCorrect ? 'text-green-600' : 'text-red-500'}`}>
                        {isCorrect ? translations.correct : `${translations.incorrect} ${item.correctAnswer}`}
                      </p>
                    )}
                  </div>
                );
              })}
            </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CEFRLevel, Language, StoryResponse, StoryStyle, AppLanguage } from "../types";

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    title: {
      type: Type.STRING,
      description: "The title of the story (or chapter) in the target language."
    },
    content: {
      type: Type.STRING,
      description: "The main body of the story in the target language. Use \\n\\n to separate paragraphs."
    },
    englishTranslation: {
      type: Type.STRING,
      description: "A full translation of the story in the requested OUTPUT LANGUAGE."
    },
    quiz: {
      type: Type.ARRAY,
      description: "A reading comprehension quiz with 3 questions in the TARGET LANGUAGE.",
      items: {
        type: Type.OBJECT,
        properties: {
          question: { type: Type.STRING, description: "The question in the TARGET LANGUAGE (not English)." },
          options: { 
            type: Type.ARRAY, 
            description: "3 possible answers in the TARGET LANGUAGE.",
            items: { type: Type.STRING } 
          },
          correctAnswer: { type: Type.STRING, description: "The correct answer string, which must match one of the options." }
        },
        required: ["question", "options", "correctAnswer"]
      }
    }
  },
  required: ["title", "content", "englishTranslation", "quiz"]
};

// Helper to get specific vocabulary count based on level - bumped numbers for better coverage
const getVocabCount = (level: CEFRLevel): string => {
  if (level.startsWith("A1")) return "25-35"; 
  if (level.startsWith("A2")) return "20-28";
  if (level.startsWith("B1")) return "18-24";
  if (level.startsWith("B2")) return "15-20";
  return "12-18"; 
};

// Helper to get strict grammatical and structural constraints
const getLevelConstraints = (level: CEFRLevel): string => {
  switch (level) {
    case "A1.1":
      return `
        CRITICAL: LEVEL A1.1 (ABSOLUTE BEGINNER) - EXTREMELY RESTRICTIVE
        1. TENSES: Use ONLY Present Simple (e.g., "It is", "She has"). ABSOLUTELY NO Past, NO Future, NO Continuous tenses.
        2. VERBS: Use only the top 50 most basic verbs (be, have, do, go, see, eat, drink, sleep, want, like).
        3. SYNTAX: Subject-Verb-Object (SVO) sentences ONLY. 
        4. CONNECTORS: Use ONLY "and". DO NOT USE "but", "because", "so", "or".
        5. SENTENCE LENGTH: Max 5-7 words per sentence.
        6. TOPICS: Concrete, visible objects only.
      `;
    case "A1.2":
      return `
        CRITICAL: LEVEL A1.2 (BEGINNER)
        1. TENSES: Mostly Present Simple. Limited high-frequency Past Simple ('was', 'did', 'went').
        2. SYNTAX: Simple sentences. Basic questions (Who, What, Where).
        3. CONNECTORS: "and", "but", "or".
        4. SENTENCE LENGTH: Average 6-8 words.
      `;
    case "A1.3":
      return `
        CRITICAL: LEVEL A1.3 (ELEMENTARY)
        1. TENSES: Present Simple, Present Continuous, Simple Past, 'Going to' future.
        2. SYNTAX: Compound sentences allowed.
        3. CONNECTORS: "and", "but", "or", "because".
      `;
    case "A2.1":
      return `
        CRITICAL: LEVEL A2.1 (HIGH ELEMENTARY)
        1. TENSES: Past Simple (Narrative). Future with 'will'. Imperatives.
        2. SYNTAX: Comparatives and Superlatives. Adverbs of frequency.
        3. CONNECTORS: Sequencing words (first, next, then, finally).
      `;
    case "A2.2":
      return `
        CRITICAL: LEVEL A2.2 (PRE-INTERMEDIATE)
        1. TENSES: Present Perfect for experience. Modal verbs (must, should, have to).
        2. SYNTAX: Zero/First Conditional. Relative clauses with "who" or "which".
      `;
    case "B1.1":
      return `
        LEVEL B1.1 (INTERMEDIATE)
        1. TENSES: Past Continuous, Present Perfect with for/since.
        2. SYNTAX: Simple Passive voice. Basic reported speech.
        3. CONNECTORS: "although", "however", "so that".
      `;
    case "B1.2":
      return `
        LEVEL B1.2 (HIGH INTERMEDIATE)
        1. TENSES: Past Perfect. Used to. 
        2. SYNTAX: Second Conditional. 
      `;
    case "B2.1":
      return `
        LEVEL B2.1 (UPPER INTERMEDIATE)
        1. TENSES: Future Continuous. Present Perfect Continuous.
        2. SYNTAX: Third Conditional. Mixed Conditionals. 
      `;
    case "B2.2":
      return `
        LEVEL B2.2 (PRE-ADVANCED)
        1. TENSES: All tenses naturally.
        2. SYNTAX: Complex passive forms. Inversion.
      `;
    case "C1-C2":
      return `
        LEVEL C1/C2 (ADVANCED/MASTERY)
        - Nuance, idioms, cultural references, complex literary structures.
      `;
    default:
      return "Standard grammar rules.";
  }
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string,
  style: StoryStyle,
  outputLanguage: AppLanguage,
  previousContext?: string
): Promise<StoryResponse> => {

  const vocabCount = getVocabCount(level);
  const strictLevelConstraints = getLevelConstraints(level);

  let languageConstraints = "";
  if (language === "Finnish") {
    if (level === "A1.1") {
        languageConstraints += " FINNISH A1.1 SPECIFIC: Use ONLY Nominative and Partitive. No other cases.";
    } else if (level === "A1.2") {
        languageConstraints += " FINNISH A1.2 SPECIFIC: Add Genitive and basic Inessive (-ssa/ssä).";
    }
  }

  let taskDescription = "Task: Write a short story strictly adhering to the requested proficiency level.";
  let contentContext = "";

  if (previousContext) {
    taskDescription = "Task: Write the NEXT PART (continuation) of the story provided below. Keep the same characters and setting.";
    contentContext = `
    PREVIOUS STORY CONTEXT:
    "${previousContext.slice(-1000)}"
    `;
  }

  const prompt = `
    Role: You are a language teacher and CEFR compliance expert.

    GOAL: Generate a story in ${language} at EXACTLY level ${level}.

    PARAMETERS:
    - Target Language: ${language}
    - CEFR Level: ${level}
    - Topic: ${topic}
    - Style: ${style}
    - Support Language (for translations): ${outputLanguage}

    ${contentContext}

    STRICT GRAMMAR RULES FOR ${level}:
    ${strictLevelConstraints}
    ${languageConstraints}

    VOCABULARY HIGHLIGHTING STRATEGY:
    1. Highlight approx ${vocabCount} words using the format: {word|translation}
    2. SELECTION CRITERIA:
       - DO NOT HIGHLIGHT basic words, articles, common pronouns, or high-frequency prepositions (e.g., if target is B1, skip "the", "a", "of", "and", "but", "house", "city").
       - DO NOT HIGHLIGHT words that are clearly at a LOWER level than ${level} (e.g., if level is B1, do not highlight A1/A2 words).
       - DO HIGHLIGHT words that are EXACTLY at level ${level}.
       - DO HIGHLIGHT words that are HIGHER than level ${level} (if you chose to include them for narrative depth).
       - FOCUS on verbs, nouns, and adjectives that characterize the vocabulary complexity of ${level}.
    3. The word inside the braces MUST match the exact inflected form (conjugation/declension) used in the story.

    FORMAT:
    - Return JSON matching the requested schema.
    - Content should be 200-400 words.
    - Title should be in ${language}.
    - EnglishTranslation should be the full story translated into ${outputLanguage}.
    - Quiz should be 3 questions in ${language} about the text.
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.3, // Slightly higher temperature for more varied vocab
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate story. Please verify your API key.");
  }
};

