/**
 * Enhanced Level Constraints with both POSITIVE (what to use) 
 * and NEGATIVE (what to avoid) rules for maximum accuracy.
 */
const getLevelConstraints = (level: CEFRLevel): string => {
  switch (level) {
    case "A1.1":
      return `
        LEVEL: A1.1 (BREAKTHROUGH/ABSOLUTE BEGINNER)
        - POSITIVE: Use only the 100 most common nouns and 50 most common verbs. Present Simple ONLY.
        - FORBIDDEN: NO Past tense, NO Future tense, NO 'but', NO 'because', NO adjectives after nouns.
        - SENTENCES: Single-clause only. Max 6 words.
        - SITUATION: Focus on labeling concrete objects and simple "I am/He has" statements.
      `;
    case "A1.2":
      return `
        LEVEL: A1.2 (BEGINNER)
        - POSITIVE: Present Simple, basic 'be' in past ('was/were'). Connectors: 'and', 'or'.
        - FORBIDDEN: NO complex sub-clauses. NO modal verbs like 'might' or 'should'.
        - SENTENCES: Average 7 words.
        - SITUATION: Daily routines, family, immediate surroundings.
      `;
    case "A1.3":
      return `
        LEVEL: A1.3 (ELEMENTARY)
        - POSITIVE: Simple Past (narrative), Present Continuous. Connector: 'because'.
        - FORBIDDEN: NO Passive voice. NO perfect tenses (have seen).
        - SITUATION: Simple storytelling about a past event.
      `;
    case "A2.1":
      return `
        LEVEL: A2.1 (HIGH ELEMENTARY)
        - POSITIVE: Future with 'will/going to'. Basic comparatives (better than).
        - FORBIDDEN: NO Conditionals (if I were...). NO reported speech.
        - SITUATION: Shopping, traveling, basic social interactions.
      `;
    case "A2.2":
      return `
        LEVEL: A2.2 (PRE-INTERMEDIATE)
        - POSITIVE: Present Perfect (experience), Modals (can, must, should). First Conditional.
        - FORBIDDEN: NO Past Perfect. NO complex relative clauses.
        - SITUATION: Describing dreams, plans, and personal history in detail.
      `;
    case "B1.1":
      return `
        LEVEL: B1.1 (INTERMEDIATE)
        - POSITIVE: Passive Voice (simple), Second Conditional. Used to.
        - FORBIDDEN: NO Future Perfect. NO complex literary idioms.
        - SITUATION: Explaining opinions, plots of books/movies, unexpected problems.
      `;
    case "B1.2":
      return `
        LEVEL: B1.2 (HIGH INTERMEDIATE)
        - POSITIVE: Past Perfect, Reported Speech. Although/Even though.
        - SITUATION: Professional contexts, technical explanations, abstract thoughts.
      `;
    case "B2.1":
      return `
        LEVEL: B2.1 (UPPER INTERMEDIATE)
        - POSITIVE: Mixed Conditionals, Future Continuous.
        - SITUATION: Debating, explaining pros/cons, complex social issues.
      `;
    case "B2.2":
      return `
        LEVEL: B2.2 (PRE-ADVANCED)
        - POSITIVE: Inversion for emphasis, complex phrasal verbs.
        - SITUATION: Nuanced storytelling, irony, formal vs informal registers.
      `;
    case "C1-C2":
      return `
        LEVEL: C1/C2 (ADVANCED/MASTERY)
        - POSITIVE: Use the full range of the language. Idiomatic, academic, and literary structures.
        - SITUATION: Subtle nuances, cultural depth, and complex professional discourse.
      `;
    default:
      return "General language use.";
  }
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string,
  style: StoryStyle,
  outputLanguage: AppLanguage,
  previousContext?: string
