  let taskDescription = "Task: Write a short story strictly adhering to the requested proficiency level.";
  let contentContext = "";

  if (previousContext) {
    taskDescription = "Task: Write the NEXT PART (continuation) of the story provided below. Keep the same characters and setting.";
    contentContext = `
    PREVIOUS STORY CONTEXT:
    "${previousContext.slice(-1000)}"
    `;
  }

  const prompt = `
    Role: You are a Language Learning Expert (CEFR Auditor).

    GOAL: Generate a story in ${language} at EXACTLY level ${level}.

    PARAMETERS:
    - Target Language: ${language}
    - CEFR Level: ${level}
    - Topic: ${topic}
    - Style: ${style}
    - Support Language (for translations): ${outputLanguage}

    ${contentContext}

    PEDAGOGICAL RULES FOR LEVEL ${level}:
    ${strictLevelConstraints}
    ${languageConstraints}

    VOCABULARY HIGHLIGHTING (INTERACTIVE LEARNING):
    1. Highlight approx ${vocabCount} words using the format: {word|translation}
    2. SELECTION LOGIC:
       - DO NOT highlight words from levels LOWER than ${level}. 
       - If the level is B1, assume the user knows A1/A2 words (e.g., skip 'apple', 'run', 'happy').
       - DO highlight words that are precisely at ${level} or higher.
       - Focus on verbs, nouns, and descriptors that define the difficulty of ${level}.
       - PROHIBITED: Do not highlight articles, pronouns, or basic prepositions (the, in, at, he, she).
    3. The word in {word|...} MUST exactly match the inflected form (case/gender/tense) used in the sentence.

    FORMAT REQUIREMENTS:
    - JSON response only.
    - Content: 200-400 words.
    - EnglishTranslation: Clear, natural translation into ${outputLanguage}.
    - Quiz: 3 reading comprehension questions in ${language}.
  `;

  try {
    const response = await genAI.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.25, // Lower temperature for more consistent level adherence
        thinkingConfig: { thinkingBudget: 4096 } // Large budget to ensure the model audits its own leveling logic
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as StoryResponse;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate story. Please check your network or API key.");
  }
};

