      />
      <header className="mx-auto max-w-7xl mb-10 text-center relative">
        <button onClick={() => setIsSettingsOpen(true)} className="absolute right-0 top-0 p-2 text-gray-400 hover:text-indigo-600 transition-colors">
          <SettingsIcon className="w-6 h-6" />
        </button>
        <div className="flex items-center justify-center space-x-3 mb-2">
            <div className="p-2 bg-indigo-600 rounded-lg text-white"><BookMarked className="w-8 h-8" /></div>
            <h1 className="text-3xl font-bold tracking-tight text-gray-900 sm:text-4xl">{t.appTitle}</h1>
        </div>
        <p className="text-lg text-gray-600 max-w-2xl mx-auto">{t.appSubtitle}</p>
      </header>

      <main className="mx-auto max-w-7xl">
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12">
          <div className="lg:col-span-4">
            <div className="sticky top-8 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-gray-900/5">
              <div className={`bg-gradient-to-r ${themeGradient} px-6 py-4`}>
                <h2 className="flex items-center text-lg font-semibold text-white">
                  <Sparkles className="mr-2 h-5 w-5" /> {t.storySettings}
                </h2>
              </div>
              <div className="space-y-6 p-6">
                {/* Adding explicit generic type parameters to ensure correct inference for specific string unions */}
                <Selector<Language> label={t.targetLanguage} value={language} options={LANGUAGES} onChange={setLanguage} disabled={generation.isLoading || isGeneratingNext} getLabel={(opt) => languageLabels[opt]} />
                <Selector<CEFRLevel> label={t.languageLevel} value={level} options={LEVELS} onChange={setLevel} disabled={generation.isLoading || isGeneratingNext} getLabel={(opt) => levelDescriptions[opt]} />
                <Selector<StoryStyle> label={t.storyStyle} value={storyStyle} options={STORY_STYLES} onChange={setStoryStyle} disabled={generation.isLoading || isGeneratingNext} getLabel={(opt) => storyStyleLabels[opt]} />

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-gray-700">{t.storyDescription}</label>
                  <textarea value={storyDescription} onChange={(e) => setStoryDescription(e.target.value)} placeholder={t.descPlaceholder} className="w-full h-32 rounded-lg border border-gray-300 px-4 py-3 focus:ring-1 focus:ring-indigo-500 outline-none" disabled={generation.isLoading || isGeneratingNext} />
                  <div className="pt-2">
                    <div className="flex items-center gap-1 mb-2 text-xs font-medium text-gray-400 uppercase tracking-wide"><Tag className="w-3 h-3" /><span>{t.suggestedTopics}</span></div>
                    <div className="flex flex-wrap gap-2">
                      {currentSuggestedTopics.map((tag) => (
                        <button key={tag} onClick={() => handleTagClick(tag)} disabled={generation.isLoading || isGeneratingNext} className="px-3 py-1 text-xs font-medium text-indigo-700 bg-indigo-50 rounded-full border border-indigo-100 hover:bg-indigo-100 transition-colors">
                          + {tag}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
                <button onClick={handleGenerate} disabled={generation.isLoading || isGeneratingNext || !storyDescription.trim()} className="flex w-full items-center justify-center rounded-xl bg-indigo-600 px-4 py-4 font-bold text-white shadow-md hover:bg-indigo-700 transition-all disabled:bg-gray-300">
                  {generation.isLoading ? t.startingStory : <>{t.newStory} <Send className="ml-2 h-4 w-4" /></>}
                </button>
              </div>
            </div>
          </div>
          <div className="flex flex-col items-center lg:col-span-8">
            {generation.isLoading && <LoadingState message={t.startingStory} />}
