            {!generation.isLoading && !generation.error && !currentStory && (
              <div className="flex h-96 w-full flex-col items-center justify-center rounded-3xl border-2 border-dashed border-gray-200 bg-white/50 text-center">
                <BookMarked className="h-10 w-10 text-gray-200 mb-4" />
                <h3 className="text-xl font-medium text-gray-500">{t.readyToRead}</h3>
                <p className="mt-1 text-gray-400">{t.readyPrompt}</p>
              </div>
            )}
            {currentStory && (
              <StoryDisplay 
                story={currentStory} language={languageLabels[language]} styleLabel={currentStyleLabel} level={level}
                onNextPage={handleNextPage} onPrevPage={handlePrevPage} canGoNext={true} canGoPrev={pageIndex > 0}
                hasNextPageInHistory={pageIndex < storyPages.length - 1} isGeneratingNext={isGeneratingNext} currentPage={pageIndex + 1} translations={t}
              />
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

