        LEVEL: A2.1 (HIGH ELEMENTARY)
        - POSITIVE: Future 'will', basic Comparatives.
        - FORBIDDEN: NO Present Perfect, NO Modal verbs like 'should' or 'must'.
      `;
    case "A2.2":
      return `
        LEVEL: A2.2 (PRE-INTERMEDIATE)
        - POSITIVE: Present Perfect, Modal verbs, First Conditional.
        - FORBIDDEN: NO Past Perfect, NO Third Conditional, NO Passive Voice.
      `;
    case "B1.1":
      return `
        LEVEL: B1.1 (INTERMEDIATE)
        - POSITIVE: Simple Passive Voice, Second Conditional.
        - FORBIDDEN: NO Future Perfect, NO Subjunctive Mood, NO Inversion.
      `;
    case "B1.2":
      return `
        LEVEL: B1.2 (HIGH INTERMEDIATE)
        - POSITIVE: Past Perfect, Reported Speech, 'although'.
        - FORBIDDEN: NO Mixed Conditionals, NO complex Gerund vs Infinitive nuances.
      `;
    case "B2.1":
      return `
        LEVEL: B2.1 (UPPER INTERMEDIATE)
        - POSITIVE: Future Continuous, Mixed Conditionals.
        - FORBIDDEN: NO Archaic vocabulary, NO overly formal academic structures.
      `;
    default:
      return "Ensure natural use of the language appropriate for the selected CEFR level.";
  }
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string,
  style: StoryStyle,
  outputLanguage: AppLanguage,
  previousContext?: string
): Promise<StoryResponse> => {

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const vocabCount = getVocabCount(level);
  const strictLevelConstraints = getLevelConstraints(level);

  const prompt = `
    Role: Senior Language Education Specialist & CEFR Auditor.

    TASK: Generate a ${language} story at EXACTLY level ${level}.
    ${previousContext ? `CONTEXT: This is a continuation of the previous part: "${previousContext}"` : ""}

    SYSTEMIC WORKFLOW:
    1. DRAFTING: Create a story about "${topic}" in "${style}" style.
    2. AUDITING: Scan the draft for FORBIDDEN grammar or words too easy/hard for ${level}.
    3. REFINING: Rewrite sentences that violate the proficiency constraints.
    4. HIGHLIGHTING: Select ${vocabCount} words at or above ${level} difficulty.

    CONSTRAINTS FOR ${level}:
    ${strictLevelConstraints}

    VOCABULARY METADATA RULES:
    - For every highlighted {word|translation}, you MUST categorize its CEFR difficulty in the "vocabularyMetadata" object.
    - Example: "vocabularyMetadata": { "exploration": { "level": "B2", "reason": "Academic abstract noun" } }

    FORMAT:
    - Return JSON matching the schema.
    - Content must be in ${language}.
    - englishTranslation must be in ${outputLanguage}.
    - quiz must be in ${language}.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 4000 }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Generation failed");
    return JSON.parse(text.trim()) as StoryResponse;
  } catch (error) {
    console.error("API Error:", error);
    throw new Error("Could not generate story. Please try again.");
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { BookMarked, Sparkles, Send, Tag, Settings as SettingsIcon } from 'lucide-react';
import { LANGUAGES, LEVELS, LEVEL_SPECIFIC_TOPICS, STORY_STYLES, LEVEL_DESCRIPTIONS, STORY_STYLE_LABELS, APP_LANGUAGES, LANGUAGE_LABELS } from './constants';
import { Language, CEFRLevel, StoryStyle, StoryResponse, AppLanguage } from './types';
import { Selector } from './components/Selector';
import { StoryDisplay } from './components/StoryDisplay';
import { LoadingState } from './components/LoadingState';
import { SettingsModal } from './components/SettingsModal';
import { generateStory } from './services/geminiService';
import { TRANSLATIONS } from './translations';

const STORAGE_KEYS = {
  LANGUAGE: 'linguatale_pref_language',
  LEVEL: 'linguatale_pref_level',
  STYLE: 'linguatale_pref_style',
  APP_LANGUAGE: 'linguatale_app_language'
};

const App: React.FC = () => {
  const [appLanguage, setAppLanguage] = useState<AppLanguage>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.APP_LANGUAGE);
    return (saved && APP_LANGUAGES.includes(saved as AppLanguage)) ? (saved as AppLanguage) : "English";
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const t = TRANSLATIONS[appLanguage] || TRANSLATIONS["English"];
  const levelDescriptions = LEVEL_DESCRIPTIONS[appLanguage] || LEVEL_DESCRIPTIONS["English"];
  const storyStyleLabels = STORY_STYLE_LABELS[appLanguage] || STORY_STYLE_LABELS["English"];
  const languageLabels = LANGUAGE_LABELS[appLanguage] || LANGUAGE_LABELS["English"];

  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LANGUAGE);
    return (saved && LANGUAGES.includes(saved as Language)) ? (saved as Language) : "English";
  });

  const [level, setLevel] = useState<CEFRLevel>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LEVEL);
    return (saved && LEVELS.includes(saved as CEFRLevel)) ? (saved as CEFRLevel) : "A1.1";
  });

  const [storyStyle, setStoryStyle] = useState<StoryStyle>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.STYLE);
    return (saved && STORY_STYLES.includes(saved as StoryStyle)) ? (saved as StoryStyle) : "Standard";
  });

  const [storyDescription, setStoryDescription] = useState<string>("");

  // History for pagination and state management
  const [storyHistory, setStoryHistory] = useState<StoryResponse[]>([]);
  const [currentIndex, setCurrentIndex] = useState(-1);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Dynamic Topics based on Level
  const currentSuggestedTopics = useMemo(() => {
    const category = level.startsWith("A1") ? "A1" : 
                     level.startsWith("A2") ? "A2" :
                     level.startsWith("B1") ? "B1" :
                     level.startsWith("B2") ? "B2" : "C1";
    // Fix: Fixed truncated reference to LEVEL_SPECIFIC_TOPICS and handled potential undefined keys
    return LEVEL_SPECIFIC_TOPICS[appLanguage]?.[category] || LEVEL_SPECIFIC_TOPICS["English"]?.["A1"] || [];
  }, [level, appLanguage]);

  // Persist preferences
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.APP_LANGUAGE, appLanguage);
    localStorage.setItem(STORAGE_KEYS.LANGUAGE, language);
    localStorage.setItem(STORAGE_KEYS.LEVEL, level);
    localStorage.setItem(STORAGE_KEYS.STYLE, storyStyle);
  }, [appLanguage, language, level, storyStyle]);

  const handleGenerateNew = async () => {
    setIsGenerating(true);
    setError(null);
    try {
      const topic = storyDescription.trim() || (currentSuggestedTopics[0] || "A random adventure");
      const newStory = await generateStory(language, level, topic, storyStyle, appLanguage);
      setStoryHistory([newStory]);
      setCurrentIndex(0);
    } catch (err: any) {
      setError(err.message || t.errorGenerating);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleNextPage = async () => {
    if (currentIndex < storyHistory.length - 1) {
      setCurrentIndex(prev => prev + 1);
      return;
    }

    setIsGenerating(true);
    setError(null);
    try {
      const lastStory = storyHistory[storyHistory.length - 1];
      const nextPart = await generateStory(
        language, 
        level, 
        `Continuation of: ${lastStory.title}`, 
        storyStyle, 
        appLanguage, 
        lastStory.content
      );
      setStoryHistory(prev => [...prev, nextPart]);
      setCurrentIndex(prev => prev + 1);
    } catch (err: any) {
      setError(err.message || t.errorGenerating);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePrevPage = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const currentStory = currentIndex >= 0 ? storyHistory[currentIndex] : null;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <header className="sticky top-0 z-40 w-full bg-white/80 backdrop-blur-md border-b border-gray-200">
        <div className="mx-auto max-w-7xl px-4 py-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="rounded-xl bg-indigo-600 p-2 text-white shadow-lg">
                <BookMarked className="h-6 w-6" />
              </div>
              <div>
                <h1 className="text-xl font-bold tracking-tight text-gray-900">{t.appTitle}</h1>
                <p className="hidden text-xs font-medium text-gray-500 sm:block">{t.appSubtitle}</p>
              </div>
            </div>

            <button
              onClick={() => setIsSettingsOpen(true)}
              className="rounded-full p-2 text-gray-500 hover:bg-gray-100 hover:text-indigo-600 transition-colors"
            >
              <SettingsIcon className="h-6 w-6" />
            </button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12">
          {/* Sidebar - Controls */}
          <aside className="lg:col-span-4 xl:col-span-3">
            <div className="sticky top-24 space-y-6 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-gray-900/5">
              <div className="flex items-center space-x-2 border-b border-gray-100 pb-4">
                <Sparkles className="h-5 w-5 text-indigo-600" />
                <h2 className="text-lg font-bold text-gray-900">{t.storySettings}</h2>
              </div>

              <Selector<Language>
                label={t.targetLanguage}
                value={language}
                options={LANGUAGES}
                onChange={setLanguage}
                getLabel={(opt) => languageLabels[opt]}
              />

              <Selector<CEFRLevel>
                label={t.languageLevel}
                value={level}
                options={LEVELS}
                onChange={setLevel}
                getLabel={(opt) => levelDescriptions[opt]}
              />

              <Selector<StoryStyle>
                label={t.storyStyle}
                value={storyStyle}
                options={STORY_STYLES}
                onChange={setStoryStyle}
                getLabel={(opt) => storyStyleLabels[opt]}
              />

              <div className="space-y-2">
                <label className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                  <Tag className="h-4 w-4 text-indigo-500" />
                  {t.storyDescription}
                </label>
                <textarea
                  value={storyDescription}
                  onChange={(e) => setStoryDescription(e.target.value)}
                  placeholder={t.descPlaceholder}
                  rows={3}
                  className="w-full rounded-lg border border-gray-300 px-4 py-2 text-sm text-gray-700 shadow-sm focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500"
                />
              </div>

              <div className="space-y-3">
                <p className="text-xs font-bold uppercase tracking-wider text-gray-400">{t.suggestedTopics}</p>
                <div className="flex flex-wrap gap-2">
                  {currentSuggestedTopics.map((topic) => (
                    <button
                      key={topic}
                      onClick={() => setStoryDescription(topic)}
                      className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-medium text-indigo-700 transition-colors hover:bg-indigo-100"
                    >
                      {topic}
                    </button>
                  ))}
                </div>
              </div>

              <button
                onClick={handleGenerateNew}
                disabled={isGenerating}
                className="flex w-full items-center justify-center space-x-2 rounded-xl bg-indigo-600 px-4 py-3 font-bold text-white shadow-lg shadow-indigo-200 transition-all hover:bg-indigo-700 hover:shadow-indigo-300 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:opacity-70"
              >
                {isGenerating && !currentStory ? (
                  <LoadingState message={t.startingStory} />
                ) : (
                  <>
                    <Send className="h-5 w-5" />
                    <span>{t.newStory}</span>
                  </>
                )}
              </button>
            </div>
          </aside>

          {/* Main Content - Story Display */}
          <section className="lg:col-span-8 xl:col-span-9">
            {isGenerating && !currentStory ? (
              <div className="mt-12">
                <LoadingState message={t.startingStory} />
              </div>
            ) : error ? (
              <div className="rounded-xl bg-red-50 p-4 text-sm text-red-700 ring-1 ring-red-200">
                {error}
              </div>
            ) : currentStory ? (
              <StoryDisplay
                story={currentStory}
                language={languageLabels[language]}
                styleLabel={storyStyleLabels[storyStyle]}
                level={level}
                currentPage={currentIndex + 1}
                onNextPage={handleNextPage}
                onPrevPage={handlePrevPage}
                canGoPrev={currentIndex > 0}
                canGoNext={true}
                hasNextPageInHistory={currentIndex < storyHistory.length - 1}
                isGeneratingNext={isGenerating}
                translations={t}
              />
            ) : (
              <div className="flex h-full min-h-[400px] flex-col items-center justify-center rounded-2xl border-2 border-dashed border-gray-200 bg-white p-12 text-center">
                <div className="mb-4 rounded-full bg-indigo-50 p-4 text-indigo-600">
                  <BookMarked className="h-12 w-12" />
                </div>
                <h3 className="text-xl font-bold text-gray-900">{t.readyToRead}</h3>
                <p className="mt-2 text-gray-500">{t.readyPrompt}</p>
              </div>
            )}
          </section>
        </div>
      </main>

      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        appLanguage={appLanguage}
        onLanguageChange={setAppLanguage}
        translations={t}
      />
    </div>
  );
};

