        {/* Pagination Controls */}
        <div className="flex items-center justify-between border-t border-gray-100 dark:border-gray-800 pt-8 not-italic">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg border border-gray-200 bg-white px-5 py-2.5 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed dark:border-gray-700 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>{translations.previousPage}</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className={`group flex items-center space-x-2 rounded-lg px-6 py-2.5 text-sm font-bold shadow-sm transition-all disabled:opacity-70 disabled:cursor-not-allowed
                    ${!hasNextPageInHistory 
                        ? "bg-indigo-600 text-white hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 shadow-indigo-200 dark:shadow-none" 
                        : "border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                    }
                `}
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>{translations.creatingNextPage}</span>
                     </>
                ) : (
                    <>
                        <span>{translations.nextPage}</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>

        <div className="flex justify-center border-t border-gray-100 dark:border-gray-800 pt-8 not-italic">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-semibold text-indigo-600 hover:text-indigo-800 dark:text-indigo-400 dark:hover:text-indigo-300 focus:outline-none transition-colors"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? translations.hideTranslation : translations.showTranslation}</span>
            </button>
        </div>

        {showTranslation && (
            <div className="animate-fade-in rounded-xl bg-gray-50 p-6 text-gray-700 ring-1 ring-gray-900/5 not-italic dark:bg-gray-800 dark:text-gray-300 dark:ring-white/5 shadow-inner">
                <h3 className="mb-3 text-xs font-bold uppercase tracking-wider text-gray-400 dark:text-gray-500">{translations.translationTitle}</h3>
                <p className="whitespace-pre-line leading-relaxed text-lg">{story.englishTranslation}</p>
            </div>
        )}

        <div className="mt-8 border-t border-gray-100 dark:border-gray-800 pt-10 not-italic">
            <div className="flex items-center space-x-3 mb-8">
                <div className="rounded-lg bg-indigo-100 p-2 dark:bg-indigo-900/30">
                   <HelpCircle className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
                </div>
                <h3 className="text-xl font-bold text-gray-900 dark:text-white">{translations.comprehensionQuiz}</h3>
            </div>

            <div className="space-y-6">
              {story.quiz.map((item, index) => {
                const selectedAnswer = quizAnswers[index];
                const isCorrect = selectedAnswer === item.correctAnswer;
                const hasAnswered = selectedAnswer != null;

                return (
                  <div key={index} className="group relative rounded-2xl border border-gray-200 bg-gray-50/50 p-6 transition-all hover:bg-white hover:shadow-md dark:border-gray-700 dark:bg-gray-800/50 dark:hover:bg-gray-800 overflow-hidden">
                    <p className="mb-4 text-lg font-medium text-gray-900 dark:text-gray-200">
                      <span className="mr-3 inline-block rounded-md bg-white px-2 py-0.5 text-sm font-bold text-indigo-600 shadow-sm ring-1 ring-gray-200 dark:bg-gray-700 dark:text-indigo-400 dark:ring-gray-600">{index + 1}</span>
                      {item.question}
                    </p>

                    <div className="space-y-3">
                      {item.options.map((option) => {
                        let buttonStyle = "border-gray-200 bg-white text-gray-700 hover:border-indigo-300 hover:bg-indigo-50 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700";
                        let icon = null;

                        // Check state variables for specific animations
                        const isSelected = selectedAnswer === option;
                        const isCorrectOption = option === item.correctAnswer;

                        if (hasAnswered) {
                           if (isCorrectOption) {
                             buttonStyle = "border-green-500 bg-green-50 text-green-900 font-semibold ring-1 ring-green-500 dark:bg-green-900/30 dark:text-green-300 dark:border-green-500";
                             icon = <CheckCircle2 className="h-5 w-5 text-green-600 dark:text-green-400 animate-bounce" />;
                           } else if (isSelected) {
                             buttonStyle = "border-red-300 bg-red-50 text-red-900 dark:bg-red-900/30 dark:text-red-300 dark:border-red-500";
                             icon = <XCircle className="h-5 w-5 text-red-500 dark:text-red-400" />;
                           } else {
                             buttonStyle = "border-gray-200 bg-gray-50 text-gray-400 opacity-50 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-500";
                           }
                        }

                        return (
                          <button
                            key={option}
                            onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                            disabled={hasAnswered}
                            className={`flex w-full items-center justify-between rounded-xl border px-5 py-3.5 text-left text-base font-medium transition-all ${buttonStyle} ${!hasAnswered ? "active:scale-[0.99]" : ""}`}
                          >
                            <span>{option}</span>
                            {icon}
                          </button>
                        );
                      })}
                    </div>

                    {hasAnswered && isCorrect && (
                         <div className="absolute inset-0 pointer-events-none flex items-center justify-center opacity-0 animate-pulse bg-green-400/10" />
                    )}

                    {hasAnswered && (
                      <div className={`mt-4 flex items-center space-x-2 text-sm font-bold animate-fade-in ${isCorrect ? 'text-green-700 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                         {isCorrect && <Sparkles className="h-4 w-4" />}
                         <span>{isCorrect ? translations.correct : `${translations.incorrect} ${item.correctAnswer}`}</span>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { BookMarked, Sparkles, Send, Tag, Settings as SettingsIcon, Library } from 'lucide-react';
import { LANGUAGES, LEVELS, LEVEL_SPECIFIC_TOPICS, STORY_STYLES, LEVEL_DESCRIPTIONS, STORY_STYLE_LABELS, APP_LANGUAGES, LANGUAGE_LABELS, LANGUAGE_THEMES } from './constants';
import { Language, CEFRLevel, GenerationState, StoryStyle, StoryResponse, AppLanguage, SavedStory, Theme } from './types';
import { Selector } from './components/Selector';
import { StoryDisplay } from './components/StoryDisplay';
import { LoadingState } from './components/LoadingState';
import { SettingsModal } from './components/SettingsModal';
import { SavedStoriesModal } from './components/SavedStoriesModal';
import { generateStory } from './services/geminiService';
import { TRANSLATIONS } from './translations';

const STORAGE_KEYS = {
  LANGUAGE: 'linguatale_pref_language',
  LEVEL: 'linguatale_pref_level',
  STYLE: 'linguatale_pref_style',
  APP_LANGUAGE: 'linguatale_app_language',
  SAVED_STORIES: 'linguatale_saved_stories',
  THEME: 'linguatale_theme'
};

const App: React.FC = () => {
  const [appLanguage, setAppLanguage] = useState<AppLanguage>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.APP_LANGUAGE);
    return (saved && APP_LANGUAGES.includes(saved as AppLanguage)) ? (saved as AppLanguage) : "English";
  });

  const [theme, setTheme] = useState<Theme>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.THEME);
    if (saved === 'dark' || saved === 'light') return saved;
    return 'light';
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLibraryOpen, setIsLibraryOpen] = useState(false);

  // Immersive Focus Mode State
  const [isFocused, setIsFocused] = useState(false);

  const t = TRANSLATIONS[appLanguage] || TRANSLATIONS["English"];
  const levelDescriptions = LEVEL_DESCRIPTIONS[appLanguage] || LEVEL_DESCRIPTIONS["English"];
  const storyStyleLabels = STORY_STYLE_LABELS[appLanguage] || STORY_STYLE_LABELS["English"];
  const languageLabels = LANGUAGE_LABELS[appLanguage] || LANGUAGE_LABELS["English"];

  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LANGUAGE);
    return (saved && LANGUAGES.includes(saved as Language)) ? (saved as Language) : "English";
  });

  const [level, setLevel] = useState<CEFRLevel>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LEVEL);
    return (saved && LEVELS.includes(saved as CEFRLevel)) ? (saved as CEFRLevel) : "A1.1";
  });

  const [storyStyle, setStoryStyle] = useState<StoryStyle>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.STYLE);
    return (saved && STORY_STYLES.includes(saved as StoryStyle)) ? (saved as StoryStyle) : "Standard";
  });

  const [storyDescription, setStoryDescription] = useState<string>("");

  const [storyHistory, setStoryHistory] = useState<StoryResponse[]>([]);
  const [currentIndex, setCurrentIndex] = useState(-1);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [savedStories, setSavedStories] = useState<SavedStory[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.SAVED_STORIES);
      if (saved) {
        let parsed = JSON.parse(saved);
        parsed = parsed.map((s: any) => ({
          ...s,
          style: s.style === "Bedtime Story" ? "Bedtime" : 
                 s.style === "Dialogue-heavy" ? "Dialogue" : s.style
        }));
        return parsed;
      }
      return [];
    } catch (e) {
      console.error("Failed to parse saved stories", e);
      return [];
    }
  });

  const [currentStoryId, setCurrentStoryId] = useState<string>(() => crypto.randomUUID());

  const currentSuggestedTopics = useMemo(() => {
    return LEVEL_SPECIFIC_TOPICS[appLanguage]?.[level] || LEVEL_SPECIFIC_TOPICS["English"]?.["A1.1"] || [];
  }, [level, appLanguage]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.APP_LANGUAGE, appLanguage);
    localStorage.setItem(STORAGE_KEYS.LANGUAGE, language);
    localStorage.setItem(STORAGE_KEYS.LEVEL, level);
    localStorage.setItem(STORAGE_KEYS.STYLE, storyStyle);
    localStorage.setItem(STORAGE_KEYS.THEME, theme);
  }, [appLanguage, language, level, storyStyle, theme]);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.SAVED_STORIES, JSON.stringify(savedStories));
  }, [savedStories]);

  useEffect(() => {
    if (savedStories.some(s => s.id === currentStoryId) && storyHistory.length > 0) {
      setSavedStories(prev => prev.map(s => 
        s.id === currentStoryId ? { ...s, history: storyHistory } : s
      ));
    }
  }, [storyHistory, currentStoryId]);

  const handleGenerateNew = async () => {
    setIsGenerating(true);
    setIsFocused(false); // Reset focus when starting fresh
    setError(null);
    setStoryHistory([]);
    setCurrentIndex(-1);

    setCurrentStoryId(crypto.randomUUID());

    try {
      const topic = storyDescription.trim() || (currentSuggestedTopics[0] || "A random adventure");
      const newStory = await generateStory(language, level, topic, storyStyle, appLanguage);
      setStoryHistory([newStory]);
      setCurrentIndex(0);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      setError(err.message || t.errorGenerating);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleNextPage = async () => {
    if (currentIndex < storyHistory.length - 1) {
      setCurrentIndex(prev => prev + 1);
      return;
    }

    setIsGenerating(true);
    setError(null);
    try {
      const lastStory = storyHistory[storyHistory.length - 1];
      const nextPart = await generateStory(
        language, 
        level, 
        `Continuation of: ${lastStory.title}`, 
        storyStyle, 
        appLanguage, 
        lastStory.content
      );
      setStoryHistory(prev => [...prev, nextPart]);
      setCurrentIndex(prev => prev + 1);
    } catch (err: any) {
      setError(err.message || t.errorGenerating);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePrevPage = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleTopicClick = (topic: string) => {
    setStoryDescription((prev) => {
      const trimmed = prev.trim();
      if (!trimmed) return topic;
      const existing = trimmed.split(',').map(s => s.trim());
      if (existing.includes(topic)) return trimmed;
      return `${trimmed}, ${topic}`;
    });
  };

  const handleToggleBookmark = () => {
    if (savedStories.some(s => s.id === currentStoryId)) {
      setSavedStories(prev => prev.filter(s => s.id !== currentStoryId));
    } else {
      if (storyHistory.length === 0) return;

      const newSavedStory: SavedStory = {
        id: currentStoryId,
        createdAt: Date.now(),
        language,
        level,
        style: storyStyle,
        topic: storyDescription || currentSuggestedTopics[0],
        history: storyHistory,
        appLanguage
      };
      setSavedStories(prev => [newSavedStory, ...prev]);
    }
  };

  const handleLoadStory = (story: SavedStory) => {
    setLanguage(story.language);
    setLevel(story.level);
    setStoryStyle(story.style);
    setStoryDescription(story.topic);
    setStoryHistory(story.history);
    setCurrentStoryId(story.id);
    setCurrentIndex(story.history.length - 1);
    setError(null);
  };

  const handleDeleteSavedStory = (id: string) => {
    setSavedStories(prev => prev.filter(s => s.id !== id));
  };

  const currentStory = currentIndex >= 0 ? storyHistory[currentIndex] : null;
  const themeGradient = LANGUAGE_THEMES[language] || "from-indigo-500 to-purple-600";
  const isBookmarked = savedStories.some(s => s.id === currentStoryId);

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans dark:bg-gray-950 dark:text-gray-100 transition-colors duration-300">

      {/* App Header - Hidden when focused on desktop for immersion, kept on mobile */}
      <header className={`sticky top-0 z-40 w-full bg-white/80 backdrop-blur-md border-b border-gray-200 dark:bg-gray-900/80 dark:border-gray-800 transition-all duration-300 ${isFocused ? 'lg:-translate-y-full' : 'translate-y-0'}`}>
        <div className="mx-auto max-w-7xl px-4 py-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="rounded-xl bg-indigo-600 p-2 text-white shadow-lg">
                <BookMarked className="h-6 w-6" />
              </div>
              <div>
                <h1 className="text-xl font-bold tracking-tight text-gray-900 dark:text-white">{t.appTitle}</h1>
                <p className="hidden text-xs font-medium text-gray-500 dark:text-gray-400 sm:block">{t.appSubtitle}</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => setIsLibraryOpen(true)}
                className="rounded-full p-2 text-gray-500 hover:bg-gray-100 hover:text-indigo-600 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 transition-colors"
                title={t.savedStories}
              >
                <Library className="h-6 w-6" />
              </button>
              <button
                onClick={() => setIsSettingsOpen(true)}
                className="rounded-full p-2 text-gray-500 hover:bg-gray-100 hover:text-indigo-600 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 transition-colors"
                title={t.settingsTitle}
              >
                <SettingsIcon className="h-6 w-6" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className={`mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8 transition-all duration-300 ${isFocused ? 'pt-8' : ''}`}>
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12 relative">

          {/* Sidebar - Controls */}
          {/* We hide it when focused using hidden/block classes or width transition. Using absolute/opacity for smoother potential transitions, but hidden is safer for layout shifts */}
          <aside className={`transition-all duration-300 ${isFocused ? 'hidden opacity-0' : 'lg:col-span-4 xl:col-span-3 opacity-100'}`}>
            <div className="sticky top-24 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-gray-900/5 dark:bg-gray-900 dark:ring-gray-800">
              <div className={`bg-gradient-to-r ${themeGradient} px-6 py-4`}>
                <h2 className="flex items-center text-lg font-semibold text-white">
                  <Sparkles className="mr-2 h-5 w-5" /> {t.storySettings}
                </h2>
              </div>

              <div className="p-6 space-y-6">
                <Selector<Language>
                  label={t.targetLanguage}
                  value={language}
                  options={LANGUAGES}
                  onChange={setLanguage}
                  getLabel={(opt) => languageLabels[opt]}
                  disabled={isGenerating}
                />

                <Selector<CEFRLevel>
                  label={t.languageLevel}
                  value={level}
                  options={LEVELS}
                  onChange={setLevel}
                  getLabel={(opt) => levelDescriptions[opt]}
                  disabled={isGenerating}
                />

                <Selector<StoryStyle>
                  label={t.storyStyle}
                  value={storyStyle}
                  options={STORY_STYLES}
                  onChange={setStoryStyle}
                  getLabel={(opt) => storyStyleLabels[opt]}
                  disabled={isGenerating}
                />

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-gray-700 dark:text-gray-300 flex items-center gap-2">
                    <Tag className="h-4 w-4 text-indigo-500" />
                    {t.storyDescription}
                  </label>
                  <textarea
                    value={storyDescription}
                    onChange={(e) => setStoryDescription(e.target.value)}
                    placeholder={t.descPlaceholder}
                    rows={3}
                    disabled={isGenerating}
                    className="w-full rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm text-gray-900 shadow-sm placeholder:text-gray-400 focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 disabled:bg-gray-50 disabled:text-gray-500 dark:bg-gray-800 dark:border-gray-700 dark:text-white dark:placeholder:text-gray-500 dark:disabled:bg-gray-700"
                  />
                </div>

                <div className="space-y-3">
                  <p className="text-xs font-bold uppercase tracking-wider text-gray-400 dark:text-gray-500">{t.suggestedTopics}</p>
                  <div className="flex flex-wrap gap-2">
                    {currentSuggestedTopics.map((topic) => (
                      <button
                        key={topic}
                        onClick={() => handleTopicClick(topic)}
                        disabled={isGenerating}
                        className="grow rounded-full bg-indigo-50 px-3 py-1 text-xs font-medium text-indigo-700 text-center justify-center transition-colors hover:bg-indigo-100 disabled:opacity-50 dark:bg-indigo-900/30 dark:text-indigo-300 dark:hover:bg-indigo-900/50"
                      >
                        {topic}
                      </button>
                    ))}
                  </div>
                </div>

                <button
                  onClick={handleGenerateNew}
                  disabled={isGenerating}
                  className="flex w-full items-center justify-center space-x-2 rounded-xl bg-indigo-600 px-4 py-3 font-bold text-white shadow-lg shadow-indigo-200 transition-all hover:bg-indigo-700 hover:shadow-indigo-300 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:opacity-70 disabled:cursor-not-allowed dark:shadow-none dark:hover:bg-indigo-500"
                >
                  <Send className="h-5 w-5" />
                  <span>{t.newStory}</span>
                </button>
              </div>
            </div>
          </aside>

          {/* Main Content - Story Display */}
          <section className={`transition-all duration-500 ${isFocused ? 'lg:col-span-12' : 'lg:col-span-8 xl:col-span-9'}`}>
            {isGenerating && !currentStory ? (
              <div className="mt-12">
                <LoadingState message={t.startingStory} />
              </div>
            ) : error ? (
              <div className="rounded-xl bg-red-50 p-4 text-sm text-red-700 ring-1 ring-red-200 dark:bg-red-900/20 dark:text-red-300 dark:ring-red-900/50">
                {error}
              </div>
            ) : currentStory ? (
              <StoryDisplay
                story={currentStory}
                language={languageLabels[language]}
                storyStyle={storyStyle}
                styleLabel={storyStyleLabels[storyStyle]}
                level={level}
                currentPage={currentIndex + 1}
                onNextPage={handleNextPage}
                onPrevPage={handlePrevPage}
                canGoPrev={currentIndex > 0}
                canGoNext={true}
                hasNextPageInHistory={currentIndex < storyHistory.length - 1}
                isGeneratingNext={isGenerating}
                translations={t}
                isBookmarked={isBookmarked}
                onToggleBookmark={handleToggleBookmark}
                isFocused={isFocused}
                onToggleFocus={() => setIsFocused(!isFocused)}
              />
            ) : (
              <div className="flex h-full min-h-[400px] flex-col items-center justify-center rounded-2xl border-2 border-dashed border-gray-200 bg-white p-12 text-center dark:bg-gray-900 dark:border-gray-800">
                <div className="mb-4 rounded-full bg-indigo-50 p-4 text-indigo-600 dark:bg-indigo-900/20 dark:text-indigo-400">
                  <BookMarked className="h-12 w-12" />
                </div>
                <h3 className="text-xl font-bold text-gray-900 dark:text-white">{t.readyToRead}</h3>
                <p className="mt-2 text-gray-500 dark:text-gray-400">{t.readyPrompt}</p>
              </div>
            )}
          </section>
        </div>
      </main>

      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        appLanguage={appLanguage}
        onLanguageChange={setAppLanguage}
        theme={theme}
        onThemeChange={setTheme}
        translations={t}
      />

      <SavedStoriesModal 
        isOpen={isLibraryOpen}
        onClose={() => setIsLibraryOpen(false)}
        savedStories={savedStories}
        onLoadStory={handleLoadStory}
        onDeleteStory={handleDeleteSavedStory}
        translations={t}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { BookOpen, Languages, HelpCircle, CheckCircle2, XCircle, ArrowLeft, ArrowRight, Loader2, Bookmark, Maximize2, Minimize2, Sparkles } from 'lucide-react';
import { StoryResponse, StoryStyle } from '../types';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  storyStyle: StoryStyle;
  styleLabel: string;
  level: string;
  onNextPage: () => void;
  onPrevPage: () => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  hasNextPageInHistory: boolean;
  isGeneratingNext: boolean;
  currentPage: number;
  translations: Record<string, string>;
  isBookmarked: boolean;
  onToggleBookmark: () => void;
  isFocused: boolean;
  onToggleFocus: () => void;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
  pre?: string;
  post?: string;
}

/**
 * Robustly parses text into segments and attaches orphan punctuation to the relevant vocab word.
 * This ensures that "word." or "(word)" wraps as a single unit.
 */
const parseParagraph = (text: string): TextSegment[] => {
  if (!text) return [];

  const regex = /\{([^{}|]+?)\s*\|\s*([^{}|]+?)\}/g;
  const rawSegments: TextSegment[] = [];
  let lastIndex = 0;
  let match;

  // 1. Initial Split
  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      rawSegments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    const word = match[1].trim();
    const translation = match[2].trim();

    if (word && translation) {
      rawSegments.push({
        type: 'vocab',
        content: word,
        translation: translation
      });
    } else {
      // Fallback for malformed tags
      rawSegments.push({
        type: 'text',
        content: match[0]
      });
    }

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    rawSegments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  // 2. Post-process to glue punctuation
  const PREFIX_RE = /([(\["'“‘«¿¡]+)$/;
  const SUFFIX_RE = /^([.,!?:;:)\]"'”’»]+)/;

  for (let i = 0; i < rawSegments.length; i++) {
    const segment = rawSegments[i];
    if (segment.type === 'vocab') {
      if (i > 0 && rawSegments[i - 1].type === 'text') {
        const prev = rawSegments[i - 1];
        const match = prev.content.match(PREFIX_RE);
        if (match) {
          const punctuation = match[1];
          segment.pre = (segment.pre || '') + punctuation;
          prev.content = prev.content.slice(0, -punctuation.length);
        }
      }

      if (i < rawSegments.length - 1 && rawSegments[i + 1].type === 'text') {
        const next = rawSegments[i + 1];
        const match = next.content.match(SUFFIX_RE);
        if (match) {
          const punctuation = match[1];
          segment.post = (segment.post || '') + punctuation;
          next.content = next.content.slice(punctuation.length);
        }
      }
    }
  }

  return rawSegments.filter(s => s.type === 'vocab' || s.content.length > 0);
};

/**
 * Returns accessible theme classes based on the story style.
 * Increased base typography size (prose-xl) and line-height (leading-relaxed/loose).
 */
const getThemeForStyle = (style: StoryStyle) => {
  // Using prose-xl on larger screens for better readability
  const baseProse = "prose-lg md:prose-xl leading-loose";
  const baseContainer = "w-full max-w-4xl mx-auto overflow-hidden rounded-2xl bg-white dark:bg-gray-900 shadow-xl ring-1 ring-gray-900/5 dark:ring-gray-800 transition-all duration-500 ease-in-out";

  switch (style) {
    case "Adventure":
    case "Mystery":
    case "Thriller":
    case "History":
    case "Biography":
    case "Serious":
      return {
        container: `${baseContainer} font-serif`,
        headerBg: "bg-slate-800 dark:bg-slate-950",
        prose: `${baseProse} prose-slate dark:prose-invert`
      };

    case "Bedtime":
    case "Romance":
    case "Fantasy":
      return {
        container: `${baseContainer} font-serif`,
        headerBg: "bg-indigo-900 dark:bg-indigo-950",
        prose: `${baseProse} prose-indigo dark:prose-invert`
      };

    case "News":
      return {
        container: `${baseContainer} font-serif`,
        headerBg: "bg-gray-900 dark:bg-gray-950",
        prose: `${baseProse} prose-gray dark:prose-invert leading-normal` // News is tighter
      };

    case "Sci-Fi":
      return {
        container: `${baseContainer} font-sans`,
        headerBg: "bg-blue-900 dark:bg-blue-950",
        prose: `${baseProse} prose-blue dark:prose-invert`
      };

    case "Dialogue":
      return {
        container: `${baseContainer} font-sans`,
        headerBg: "bg-teal-700 dark:bg-teal-900",
        prose: `${baseProse} prose-teal dark:prose-invert space-y-6` 
      };

    case "Diary":
       return {
         container: `${baseContainer} font-sans italic`,
         headerBg: "bg-stone-600 dark:bg-stone-800",
         prose: `${baseProse} prose-stone dark:prose-invert`
       };

    default: // Standard, Funny
      return {
        container: `${baseContainer} font-sans`,
        headerBg: "bg-indigo-600 dark:bg-indigo-800",
        prose: `${baseProse} prose-indigo dark:prose-invert`
      };
  }
};

export const StoryDisplay: React.FC<StoryDisplayProps> = ({ 
  story, 
  language, 
  storyStyle,
  styleLabel, 
  level,
  onNextPage,
  onPrevPage,
  canGoPrev,
  canGoNext,
  hasNextPageInHistory,
  isGeneratingNext,
  currentPage,
  translations,
  isBookmarked,
  onToggleBookmark,
  isFocused,
  onToggleFocus
}) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, string>>({});

  useEffect(() => {
    setShowTranslation(false);
    setActiveTooltipId(null);
    setQuizAnswers({});
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [story]);

  const paragraphs = useMemo(() => {
    if (!story.content) return [];
    const normalizedContent = story.content.replace(/\\n/g, '\n');
    return normalizedContent.split(/\n+/).filter(p => p.trim().length > 0);
  }, [story.content]);

  const handleBackgroundClick = () => {
    setActiveTooltipId(null);
  };

  const handleQuizOptionClick = (questionIndex: number, option: string) => {
    setQuizAnswers(prev => ({
      ...prev,
      [questionIndex]: option
    }));
  };

  const theme = getThemeForStyle(storyStyle);

  return (
    <div className={`animate-fade-in-up ${theme.container}`}>
      {/* Header */}
      <div className={`border-b border-gray-100 dark:border-gray-800 px-6 py-4 text-white transition-colors duration-300 ${theme.headerBg}`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <BookOpen className="h-5 w-5 opacity-80" />
            <span className="font-medium opacity-90 not-italic tracking-wide">{language} • {styleLabel}</span>
          </div>
          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2">
                <span className="opacity-75 text-xs font-bold uppercase tracking-wider not-italic">{translations.page} {currentPage}</span>
                <span className="rounded-full bg-white/20 px-3 py-0.5 text-xs font-bold text-white not-italic ring-1 ring-white/30">
                    {level}
                </span>
             </div>

             {/* Divider */}
             <div className="h-4 w-px bg-white/30" />

             {/* Focus Toggle */}
             <button 
                onClick={onToggleFocus}
                className="opacity-70 hover:opacity-100 transition-opacity focus:outline-none"
                title={isFocused ? "Exit Focus Mode" : "Enter Focus Mode"}
             >
                {isFocused ? <Minimize2 className="h-4 w-4" /> : <Maximize2 className="h-4 w-4" />}
             </button>
          </div>
        </div>
      </div>

      <div className="relative space-y-10 px-6 py-10 sm:px-12">

        {/* Bookmark Button - Absolute positioning might overlap with long titles on mobile, refined top/right */}
        <div className="absolute top-6 right-6 sm:right-10 z-10">
          <button 
            onClick={onToggleBookmark}
            className={`rounded-full p-2.5 transition-all focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 shadow-sm ${
              isBookmarked 
                ? "bg-amber-100 text-amber-600 hover:bg-amber-200 dark:bg-amber-900/50 dark:text-amber-400" 
                : "bg-gray-100 text-gray-400 hover:bg-gray-200 hover:text-gray-600 dark:bg-gray-800 dark:text-gray-500 dark:hover:text-gray-300"
            }`}
            title={isBookmarked ? translations.bookmarked : translations.bookmarkStory}
          >
            <Bookmark className={`h-5 w-5 ${isBookmarked ? "fill-current" : ""}`} />
          </button>
        </div>

        {/* Story Section */}
        <section onClick={handleBackgroundClick} className="pt-4">
          <h2 className="mb-8 mr-12 text-3xl font-bold text-gray-900 dark:text-white sm:text-4xl text-center not-italic tracking-tight leading-tight">
            {story.title}
          </h2>

          <div className={`prose max-w-none text-gray-800 dark:text-gray-200 ${theme.prose}`}>
            {paragraphs.map((paragraph, pIndex) => {
              const segments = parseParagraph(paragraph);

              return (
                <p key={pIndex} className="mb-8 last:mb-0 text-justify">
                  {segments.map((segment, sIndex) => {
                    if (segment.type === 'text') {
                      return <span key={sIndex}>{segment.content}</span>;
                    }

                    const uniqueId = `${pIndex}-${sIndex}`;
                    const isOpen = activeTooltipId === uniqueId;

                    return (
                      <span key={sIndex} className="relative inline-block group whitespace-nowrap">
                        {segment.pre && <span className="mr-[1px] opacity-90">{segment.pre}</span>}
                        <span
                          role="button"
                          tabIndex={0}
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveTooltipId(isOpen ? null : uniqueId);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                              e.preventDefault();
                              e.stopPropagation();
                              setActiveTooltipId(isOpen ? null : uniqueId);
                            }
                          }}
                          className={`
                            cursor-pointer rounded border-b-[3px] font-bold transition-all outline-none px-0.5 not-italic
                            ${isOpen 
                              ? 'border-indigo-600 bg-indigo-100 text-indigo-900 dark:bg-indigo-900 dark:text-indigo-100' 
                              : 'border-indigo-300/70 text-indigo-700 hover:bg-indigo-50 hover:border-indigo-400 dark:border-indigo-700 dark:text-indigo-300 dark:hover:bg-indigo-900/40'
                            }
                          `}
                        >
                          {segment.content}
                        </span>
                        {segment.post && <span>{segment.post}</span>}

                        {isOpen && (
                          <div className="absolute bottom-full left-1/2 mb-3 z-50 -translate-x-1/2">
                            <div className="animate-fade-in relative rounded-xl bg-gray-900 px-4 py-3 text-base font-medium text-white shadow-2xl whitespace-nowrap dark:bg-gray-800 dark:ring-1 dark:ring-white/10">
                              {segment.translation}
                              <div className="absolute top-full left-1/2 -ml-2 -mt-1 h-4 w-4 -translate-x-1/2 rotate-45 bg-gray-900 dark:bg-gray-800"></div>
                            </div>
                          </div>
                        )}
                      </span>
                    );
                  })}
                </p>
              );
            })}
          </div>
        </section>

        {/* Pagination Controls */}
        <div className="flex items-center justify-between border-t border-gray-100 dark:border-gray-800 pt-8 not-italic">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-lg border border-gray-200 bg-white px-5 py-2.5 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed dark:border-gray-700 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>{translations.previousPage}</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className={`group flex items-center space-x-2 rounded-lg px-6 py-2.5 text-sm font-bold shadow-sm transition-all disabled:opacity-70 disabled:cursor-not-allowed
                    ${!hasNextPageInHistory 
                        ? "bg-indigo-600 text-white hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 shadow-indigo-200 dark:shadow-none" 
                        : "border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:border-gray-300 hover:text-indigo-600 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                    }
                `}
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>{translations.creatingNextPage}</span>
                     </>
                ) : (
                    <>
                        <span>{translations.nextPage}</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>

        <div className="flex justify-center border-t border-gray-100 dark:border-gray-800 pt-8 not-italic">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-semibold text-indigo-600 hover:text-indigo-800 dark:text-indigo-400 dark:hover:text-indigo-300 focus:outline-none transition-colors"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? translations.hideTranslation : translations.showTranslation}</span>
            </button>
        </div>

        {showTranslation && (
            <div className="animate-fade-in rounded-xl bg-gray-50 p-6 text-gray-700 ring-1 ring-gray-900/5 not-italic dark:bg-gray-800 dark:text-gray-300 dark:ring-white/5 shadow-inner">
                <h3 className="mb-3 text-xs font-bold uppercase tracking-wider text-gray-400 dark:text-gray-500">{translations.translationTitle}</h3>
                <p className="whitespace-pre-line leading-relaxed text-lg">{story.englishTranslation}</p>
            </div>
        )}

        <div className="mt-8 border-t border-gray-100 dark:border-gray-800 pt-10 not-italic">
            <div className="flex items-center space-x-3 mb-8">
                <div className="rounded-lg bg-indigo-100 p-2 dark:bg-indigo-900/30">
                   <HelpCircle className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
                </div>
                <h3 className="text-xl font-bold text-gray-900 dark:text-white">{translations.comprehensionQuiz}</h3>
            </div>

            <div className="space-y-6">
              {story.quiz.map((item, index) => {
                const selectedAnswer = quizAnswers[index];
                const isCorrect = selectedAnswer === item.correctAnswer;
                const hasAnswered = selectedAnswer != null;

                return (
                  <div key={index} className="group relative rounded-2xl border border-gray-200 bg-gray-50/50 p-6 transition-all hover:bg-white hover:shadow-md dark:border-gray-700 dark:bg-gray-800/50 dark:hover:bg-gray-800 overflow-hidden">
                    <p className="mb-4 text-lg font-medium text-gray-900 dark:text-gray-200">
                      <span className="mr-3 inline-block rounded-md bg-white px-2 py-0.5 text-sm font-bold text-indigo-600 shadow-sm ring-1 ring-gray-200 dark:bg-gray-700 dark:text-indigo-400 dark:ring-gray-600">{index + 1}</span>
                      {item.question}
                    </p>

                    <div className="space-y-3">
                      {item.options.map((option) => {
                        let buttonStyle = "border-gray-200 bg-white text-gray-700 hover:border-indigo-300 hover:bg-indigo-50 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700";
                        let icon = null;

                        // Check state variables for specific animations
                        const isSelected = selectedAnswer === option;
                        const isCorrectOption = option === item.correctAnswer;

                        if (hasAnswered) {
                           if (isCorrectOption) {
                             buttonStyle = "border-green-500 bg-green-50 text-green-900 font-semibold ring-1 ring-green-500 dark:bg-green-900/30 dark:text-green-300 dark:border-green-500";
                             icon = <CheckCircle2 className="h-5 w-5 text-green-600 dark:text-green-400 animate-bounce" />;
                           } else if (isSelected) {
                             buttonStyle = "border-red-300 bg-red-50 text-red-900 dark:bg-red-900/30 dark:text-red-300 dark:border-red-500";
                             icon = <XCircle className="h-5 w-5 text-red-500 dark:text-red-400" />;
                           } else {
                             buttonStyle = "border-gray-200 bg-gray-50 text-gray-400 opacity-50 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-500";
                           }
                        }

                        return (
                          <button
                            key={option}
                            onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                            disabled={hasAnswered}
                            className={`flex w-full items-center justify-between rounded-xl border px-5 py-3.5 text-left text-base font-medium transition-all ${buttonStyle} ${!hasAnswered ? "active:scale-[0.99]" : ""}`}
                          >
                            <span>{option}</span>
                            {icon}
                          </button>
                        );
                      })}
                    </div>

                    {hasAnswered && isCorrect && (
                         <div className="absolute inset-0 pointer-events-none flex items-center justify-center opacity-0 animate-pulse bg-green-400/10" />
                    )}

                    {hasAnswered && (
                      <div className={`mt-4 flex items-center space-x-2 text-sm font-bold animate-fade-in ${isCorrect ? 'text-green-700 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                         {isCorrect && <Sparkles className="h-4 w-4" />}
                         <span>{isCorrect ? translations.correct : `${translations.incorrect} ${item.correctAnswer}`}</span>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
        </div>
      </div>
    </div>
  );
};

