                                    } else if (isSelected) {
                                        buttonStyle = "border-red-300 bg-red-50 text-red-900 dark:bg-red-900/30 dark:text-red-300 dark:border-red-500";
                                        icon = <XCircle className="h-5 w-5 text-red-500 dark:text-red-400" />;
